DELETE FROM `quest_request_items` WHERE `ID` IN (46675 /*-Unknown-*/, 47654 /*-Unknown-*/, 47220 /*-Unknown-*/, 47219 /*-Unknown-*/, 47101 /*-Unknown-*/, 47690 /*-Unknown-*/, 47685 /*-Unknown-*/, 47688 /*-Unknown-*/, 46834 /*-Unknown-*/, 47990 /*-Unknown-*/, 47986 /*-Unknown-*/, 47890 /*-Unknown-*/, 49143 /*-Unknown-*/, 46213 /*-Unknown-*/, 48002 /*-Unknown-*/);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES
(46675, 0, 0, 0, 0, '收集一些公函，我应该就可以弄明白这个指挥官的位置在哪。     ', 25996), -- -Unknown-
(47654, 0, 0, 0, 0, '我给你带来的是沉重的负担，$n。我相信你不会失败。', 25996), -- -Unknown-
(47220, 6, 0, 0, 0, '这是什么？如此黑暗……', 25996), -- -Unknown-
(47219, 1, 0, 0, 0, '我看到的前路很明确，$n。', 25996), -- -Unknown-
(47101, 1, 0, 0, 0, '你发现什么有趣的东西了吗？', 25996), -- -Unknown-
(47690, 0, 0, 0, 0, '阿克蒙德本人……我们这是碰到了什么麻烦？', 25996), -- -Unknown-
(47685, 0, 0, 0, 0, '要么拿出机智印记，要么离我远点。', 25996), -- -Unknown-
(47688, 0, 0, 0, 0, '总要有个备用计划。你发现我们要找的了吗？', 25996), -- -Unknown-
(46834, 0, 0, 0, 0, '拜托，它们应该不能支撑更久了。', 25996), -- -Unknown-
(47990, 0, 0, 0, 0, '记住——要完美的！', 25996), -- -Unknown-
(47986, 0, 0, 0, 0, '你拿到配件了吗？', 25996), -- -Unknown-
(47890, 0, 0, 0, 0, '我知道，我知道，这个要求很离谱，但我们需要一切可能的帮助，$G小伙子:丫头;！', 25996), -- -Unknown-
(49143, 1, 0, 0, 0, '虽然泽拉走了，她的精华依然能在这场战斗中为我们提供帮助。', 25996), -- -Unknown-
(46213, 669, 0, 0, 0, '我希望你带了支援。', 25996), -- -Unknown-
(48002, 0, 0, 0, 0, '搜寻进行得怎么样？找到我的瓶子了吗？', 25996); -- -Unknown-



