(122450, @GROUP_ID+7, @ID+0, '|TInterface\\ICONS\\ABILITY_WARRIOR_COLOSSUSSMASH.BLP:20|t加洛西灭世者往后一倾，准备施放|cFFF00000|Hspell:244969|h[根除]|h|r！快跑！', 41, 0, 100, 0, 0, 86400, 138536, '加洛西灭世者 to 屠戮者'),
(122450, @GROUP_ID+8, @ID+0, '系统重启，能量改道。武器装填完毕。', 14, 0, 100, 0, 0, 86400, 132434, '加洛西灭世者 to 屠戮者'),
(122450, @GROUP_ID+9, @ID+0, '能量核心……破裂……', 14, 0, 100, 0, 0, 86972, 135268, '加洛西灭世者 to Player'),
/*
-- (122554, @GROUP_ID+0, @ID+0, '海军上将斯芙拉克丝离开了她的座舱！', 41, 0, 100, 0, 0, 0, UNKNOWN, '海军上将的座舱 to 海军上将的座舱'),
*/
(122621, @GROUP_ID+0, @ID+0, '你成功了，勇士！来吧，我们去泽尼达尔救泽拉！', 12, 0, 100, 0, 0, 86510, 134477, '大主教图拉扬 to Player'),
(122621, @GROUP_ID+1, @ID+0, '泽拉！别担心，你安全了。', 12, 0, 100, 0, 0, 86514, 132699, '大主教图拉扬 to Player'),
(122621, @GROUP_ID+2, @ID+0, '来吧，勇士。帮我护送她前往维迪卡尔。然后我们就离开！', 12, 0, 100, 0, 0, 86513, 132698, '大主教图拉扬 to Player'),
(122739, @GROUP_ID+0, @ID+0, '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t一艘军团巡洋舰正准备进行|cFFFF0000|Hspell:244627|h[齐射]|h|r！', 41, 0, 100, 0, 0, 88737, 132925, '军团巡洋舰 to 海军上将斯芙拉克丝'),
(122773, @GROUP_ID+0, @ID+0, '|TInterface\\ICONS\\ABILITY_MAGE_FIRESTARTER.BLP:20|t你已成为了|cFFF00000|Hspell:244410|h[屠戮]|h|r的目标！', 42, 0, 100, 0, 0, 86395, 132901, '屠戮者 to Player'),
/*
-- (123013, @GROUP_ID+0, @ID+0, '埃洛杜斯将军离开了他的座舱！', 41, 0, 100, 0, 0, 0, UNKNOWN, '将军的座舱 to 将军的座舱'),
-- (123020, @GROUP_ID+0, @ID+0, '首席工程师伊什卡离开了他的座舱！', 41, 0, 100, 0, 0, 0, UNKNOWN, '工程师的座舱 to 工程师的座舱'),
 */
(123085, @GROUP_ID+0, @ID+0, '要反抗、要战斗、要活下去。', 12, 0, 100, 0, 0, 88174, 135892, '邪缚苦工 to Player'),
(123085, @GROUP_ID+1, @ID+0, '魔法燃烧我们的灵魂，死亡也无法结束痛苦。', 12, 0, 100, 0, 0, 88169, 135886, '邪缚苦工 to Player'),
(123085, @GROUP_ID+2, @ID+0, '大地在痛苦蠕动。邪能燃烧一切生命。', 12, 0, 100, 0, 0, 88230, 135893, '邪缚苦工 to Player'),
(123085, @GROUP_ID+3, @ID+0, '他们不可战胜。即使死亡，他们仍能归来！', 12, 0, 100, 0, 0, 88170, 135887, '邪缚苦工 to Player'),
(123085, @GROUP_ID+4, @ID+0, '别靠近。你也会死的。', 12, 0, 100, 0, 0, 88231, 135894, '邪缚苦工 to Player'),
(123109, @GROUP_ID+0, @ID+0, '你将尝到真正的痛苦！', 12, 0, 100, 0, 0, 86705, 132503, '沸燃使徒 to Player'),
(123110, @GROUP_ID+0, @ID+0, '混沌统治一切。', 12, 0, 100, 0, 0, 37963, 132517, '影缚亵渎者 to 光铸骑兵'),
(123149, @GROUP_ID+0, @ID+0, '这边！', 14, 0, 100, 0, 0, 87921, 135519, '先知维伦 to 安塔恩灭光者'), -- BroadcastTextID: 49296 - 59574 - 71236 - 135519 - 135516 - 126824 - 111389
(123149, @GROUP_ID+1, @ID+0, '准备就绪！', 14, 0, 100, 0, 0, 87897, 135526, '先知维伦 to 安塔恩灭光者'), -- BroadcastTextID: 10982 - 135526
(123187, @GROUP_ID+0, @ID+0, '敌人来了！', 14, 0, 100, 0, 0, 87493, 135525, '奥蕾莉亚·风行者 to 鲁拉'), -- BroadcastTextID: 32397 - 32407 - 135525
(123241, @GROUP_ID+0, @ID+0, '快，快！快去告诉军需官！', 12, 0, 100, 0, 0, 0, 132349, '邪铸回收者 to 邪铸回收者'),
(123247, @GROUP_ID+0, @ID+0, '这真是个大发现。我们得把它弄走！', 12, 0, 100, 0, 0, 0, 132350, '军需官艾卡斯 to Player'),
(123301, @GROUP_ID+0, @ID+0, '伟大的黑暗无所不知！', 12, 0, 100, 0, 0, 87100, 130871, '染影克罗库 to Player'),
(123301, @GROUP_ID+1, @ID+0, '黑暗笼罩了我。', 12, 0, 100, 0, 0, 87112, 130883, '染影克罗库 to Player'),
(123413, @GROUP_ID+0, @ID+0, '唔。守门人被关闭了。', 12, 0, 100, 6, 0, 87595, 132728, '大法师伊米拉 to Player'),
(123413, @GROUP_ID+1, @ID+0, '这个构造体应该有关于启迪印记的线索。我们得唤醒它。', 12, 0, 100, 1, 0, 87588, 133367, '大法师伊米拉 to Player'),
(123413, @GROUP_ID+2, @ID+0, '我原本希望这能有用。那里有光，可没人在家。', 12, 0, 100, 0, 0, 87590, 133420, '大法师伊米拉 to Player'),
(123413, @GROUP_ID+3, @ID+0, '我需要你的帮助。打起精神，好吗？', 12, 0, 100, 0, 0, 87583, 133508, '大法师伊米拉 to Player'),
(123413, @GROUP_ID+4, @ID+0, '我或许无法直接帮助你，但我掌握了一些有趣的信息。', 15, 0, 100, 0, 0, 87586, 133549, '大法师伊米拉 to Player'),
(123413, @GROUP_ID+5, @ID+0, '大法师伊米拉挥手让你跟上她。', 16, 0, 100, 3, 0, 0, 136098, '大法师伊米拉 to Player'),
(123418, @GROUP_ID+0, @ID+0, '尝尝真正的痛苦！', 12, 0, 100, 0, 0, 0, 132503, '邪侵勇士 to Player'),
(123520, @GROUP_ID+0, @ID+0, '我可不会留情的。我们开始吧。', 12, 0, 100, 113, 0, 87571, 132869, '大执政官薇拉拉 to Player'),
(123520, @GROUP_ID+1, @ID+0, '记住，我们三个都会考虑你的表现。', 12, 0, 100, 0, 0, 87568, 135396, '大执政官薇拉拉'),
(123520, @GROUP_ID+2, @ID+0, '你可以做得更好的。', 12, 0, 100, 0, 0, 87569, 135397, '大执政官薇拉拉'),
(123520, @GROUP_ID+3, @ID+0, '够了。你证明了自己的实力。', 12, 0, 100, 0, 0, 87572, 132873, '大执政官薇拉拉 to Player'),
(123521, @GROUP_ID+0, @ID+0, '你将面对学宫大宰相加拉苏姆！', 12, 0, 100, 66, 0, 87181, 132868, '大宰相加拉苏姆 to Player'),
(123521, @GROUP_ID+1, @ID+0, '你的傲慢会毁了你。', 12, 0, 100, 0, 0, 87178, 135394, '大宰相加拉苏姆'),
(123521, @GROUP_ID+2, @ID+0, '不值一提。', 12, 0, 100, 0, 0, 87179, 135395, '大宰相加拉苏姆'), -- BroadcastTextID: 72524 - 75038 - 75038 - 135395
(123521, @GROUP_ID+3, @ID+0, '哼。看来都结束了。', 12, 0, 100, 0, 0, 87182, 132872, '大宰相加拉苏姆 to Player'),
(123522, @GROUP_ID+0, @ID+0, '愚蠢的行为，但我会满足你的。', 12, 0, 100, 66, 0, 87759, 132870, '高阶启迪者阿尔贡 to Player');

INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(123522, @GROUP_ID+1, @ID+0, '目前，你的努力还……不够。', 12, 0, 100, 0, 0, 88097, 135392, '高阶启迪者阿尔贡'),
(123522, @GROUP_ID+2, @ID+0, '这样下去，你只能勉强保命了。', 12, 0, 100, 0, 0, 87757, 135393, '高阶启迪者阿尔贡'),
(123522, @GROUP_ID+3, @ID+0, '我认为这是当之无愧的胜利。', 12, 0, 100, 0, 0, 87760, 132871, '高阶启迪者阿尔贡 to Player'),
(123668, @GROUP_ID+0, @ID+0, 'Archenon poros，先知。圣光军团与你同在。', 12, 0, 100, 113, 0, 87650, 132715, '法瑞娅队长 to Player'),
(123669, @GROUP_ID+0, @ID+0, '大守备官索沃斯肯定地哼了一声。', 16, 0, 100, 0, 0, 0, 133814, '大守备官索沃斯 to Player'),
(123670, @GROUP_ID+0, @ID+0, '“神射手”巴拉特向你致敬。', 16, 0, 100, 66, 0, 0, 133807, '“神射手”巴拉特 to Player'),
(123671, @GROUP_ID+0, @ID+0, '剑圣特拉蒙简单地点点头。', 16, 0, 100, 0, 0, 87708, 133863, '剑圣特拉蒙 to Player'),
(123671, @GROUP_ID+1, @ID+0, '剑圣特拉蒙向你致敬。', 16, 0, 100, 0, 0, 0, 134024, '剑圣特拉蒙 to Player'),
(123689, @GROUP_ID+0, @ID+0, '我将在阿古斯的烈焰中重生！我绝不……停止……战斗。', 12, 0, 100, 0, 0, 86605, 132805, '恶毒者泰勒斯塔 to 末日守卫'),
(123743, @GROUP_ID+0, @ID+0, '勇士们！这边！', 14, 0, 100, 0, 0, 87562, 133381, '奥蕾莉亚·风行者 to Player'),
(123743, @GROUP_ID+1, @ID+0, '跟我走！', 14, 0, 100, 0, 0, 87563, 135522, '奥蕾莉亚·风行者 to Player'),
(124070, @GROUP_ID+0, @ID+0, '我们开始吧。', 12, 0, 100, 0, 0, 87995, 133313, '警卫夸拉姆 to Player'), -- BroadcastTextID: 20325 - 45689 - 54679 - 67930 - 81958 - 93463 - 133313 - 126950 - 125774 - 123054 - 100420
(124077, @GROUP_ID+0, @ID+0, '这个挑战非常简单。走进去，然后一直跑到建筑的另一边。', 12, 0, 100, 0, 0, 87979, 132936, '守门人的影像 to Player'),
(124077, @GROUP_ID+1, @ID+0, '它的目标就是干掉你。祝你好运。', 12, 0, 100, 0, 0, 87980, 132950, '守门人的影像 to Player'),
(124077, @GROUP_ID+2, @ID+0, '别让激光扫中你。我估计那会很痛的。', 12, 0, 100, 0, 0, 87981, 132953, '守门人的影像 to Player'),
(124077, @GROUP_ID+3, @ID+0, '小心台阶。', 12, 0, 100, 0, 0, 87982, 132962, '守门人的影像 to Player'),
(124077, @GROUP_ID+4, @ID+0, '噢，你成功了。了不起。', 12, 0, 100, 0, 0, 87978, 133015, '守门人的影像 to Player'),
(124077, @GROUP_ID+5, @ID+0, '很好，这个试炼完成了。但这只是因为我没有足够的空间来考验你。', 12, 0, 100, 0, 0, 87983, 132973, '守门人的影像 to Player'),
(124276, @GROUP_ID+0, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空之门出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133029, 'Conversation Controller to Player'),
(124276, @GROUP_ID+1, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t废弃的瞭望台出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133032, 'Conversation Controller to Player'),
(124276, @GROUP_ID+2, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空裂口出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133031, 'Conversation Controller to Player'),
(124312, @GROUP_ID+0, @ID+0, '时间才是关键。我们决不能让军团抓到先知。', 12, 0, 100, 0, 0, 87734, 133034, '大主教图拉扬 to Player'),
(124312, @GROUP_ID+1, @ID+0, '他在这儿。', 12, 0, 100, 0, 0, 87739, 134030, '大主教图拉扬 to Player'), -- BroadcastTextID: 88241 - 134030
(124440, @GROUP_ID+0, @ID+0, '我会不断……重生……', 12, 0, 100, 0, 0, 86787, 134479, '监视者伊比达 to Player'),
(124477, @GROUP_ID+0, @ID+0, '下一个。', 12, 0, 100, 0, 0, 87711, 135488, '大主教图拉扬 to Player'),
(124477, @GROUP_ID+1, @ID+0, '又少了一个敌人。', 12, 0, 100, 0, 0, 87710, 135487, '大主教图拉扬 to Player'),
(124477, @GROUP_ID+2, @ID+0, '尝尝我的剑吧，恶魔！', 12, 0, 100, 0, 0, 87708, 135484, '大主教图拉扬 to Player'),
(124677, @GROUP_ID+0, @ID+0, '啊，很好。我已经很久没有教训过学徒了。来吧，面对我。', 12, 0, 100, 0, 0, 87573, 135398, '阿克蒙德 to Player'),
(124677, @GROUP_ID+1, @ID+0, '许多人都挑战过我，可都失败了。', 12, 0, 100, 0, 0, 87141, 133375, '阿克蒙德'),
(124677, @GROUP_ID+2, @ID+0, '你以为自己够机灵。但我知道你会是什么下场。', 12, 0, 100, 0, 0, 87142, 133376, '阿克蒙德'),
(124677, @GROUP_ID+3, @ID+0, '在我的意志下，顽抗毫无意义。我会击溃你。', 12, 0, 100, 0, 0, 87143, 133377, '阿克蒙德'),
(124677, @GROUP_ID+4, @ID+0, '哈！这将成为我教学时的最佳案例。', 12, 0, 100, 153, 0, 87144, 133378, '阿克蒙德 to Player'),
(124677, @GROUP_ID+5, @ID+0, '你会让阿古斯骄傲的。接受奖励吧。', 12, 0, 100, 397, 0, 87139, 133627, '阿克蒙德 to Player'),
(124931, @GROUP_ID+0, @ID+0, 'Krypta！', 12, 0, 100, 0, 0, 0, 133640, '克罗库山岭猎手 to Player'), -- BroadcastTextID: 17508 - 135851 - 133640
(125034, @GROUP_ID+0, @ID+0, '这座要塞只是对安托鲁斯的拙劣模仿。', 12, 0, 100, 0, 0, 86979, 135255, '领主纳斯拉克斯'),
(125034, @GROUP_ID+1, @ID+0, '我等着听你的痛苦哀嚎在殿堂中回荡。', 12, 0, 100, 0, 0, 87172, 135256, '领主纳斯拉克斯'),
(125034, @GROUP_ID+2, @ID+0, '你的傲慢会毁掉你。', 12, 0, 100, 25, 0, 87170, 135242, '领主纳斯拉克斯'),
(125034, @GROUP_ID+3, @ID+0, '没关系。我会搞定的。', 12, 0, 100, 0, 0, 87158, 135258, '领主纳斯拉克斯'),
(125034, @GROUP_ID+4, @ID+0, '就算我死了，他也会来……', 12, 0, 100, 0, 0, 87160, 135259, '领主纳斯拉克斯 to Player'),
(125099, @GROUP_ID+0, @ID+0, '占据她的暗影，奥蕾莉亚！按我教的做！', 14, 0, 100, 0, 0, 88267, 133973, '双界行者 to 奥蕾莉亚·风行者'),
(125114, @GROUP_ID+0, @ID+0, '你休想干扰重生。他们即将重获新生！', 12, 0, 100, 0, 0, 87145, 135294, '妖女阿波崔丝'),
(125114, @GROUP_ID+1, @ID+0, '一切都将重塑。一切都将毁灭！', 12, 0, 100, 0, 0, 87146, 135295, '妖女阿波崔丝'),
(125114, @GROUP_ID+2, @ID+0, '你太迟了。', 12, 0, 100, 0, 0, 87147, 135818, '妖女阿波崔丝 to Player'), -- BroadcastTextID: 65404 - 135818
(125115, @GROUP_ID+0, @ID+0, '你还不明白吗？没有邪能，暗影就会获胜！', 12, 0, 100, 0, 0, 87149, 135289, '赫拉迪卡夫人'),
(125115, @GROUP_ID+1, @ID+0, '我们的远征是唯一的救赎。一切都将在主人的烈焰中重生！', 12, 0, 100, 0, 0, 87150, 135291, '赫拉迪卡夫人'),
(125115, @GROUP_ID+2, @ID+0, '你缺乏……远见。', 12, 0, 100, 0, 0, 87151, 135292, '赫拉迪卡夫人 to Player'),
(125139, @GROUP_ID+0, @ID+0, '我们……无处……不在！', 12, 0, 100, 0, 0, 0, 114014, '纳斯雷兹姆怨毒领主 to Player'),
(125149, @GROUP_ID+0, @ID+0, '凡人的血肉之躯真脆弱。', 12, 0, 100, 0, 0, 55197, 102132, '纳斯拉克森恶魔卫士 to 光铸战争机甲'),
(125149, @GROUP_ID+1, @ID+0, '不过是小菜一碟。', 12, 0, 100, 0, 0, 55197, 102131, '纳斯拉克森恶魔卫士 to 光铸战争机甲'),
(125149, @GROUP_ID+2, @ID+0, '你竟敢在这里袭击我们？！', 12, 0, 100, 0, 0, 55197, 96662, '纳斯拉克森恶魔卫士 to 光铸战争机甲'),
(125149, @GROUP_ID+3, @ID+0, '我要把你大卸八块。', 12, 0, 100, 0, 0, 55188, 97238, '纳斯拉克森恶魔卫士 to 光铸战争机甲'), -- BroadcastTextID: 97238 - 94935
(125149, @GROUP_ID+4, @ID+0, '为您效劳。', 12, 0, 100, 0, 0, 55194, 112194, '纳斯拉克森恶魔卫士 to 光铸战争机甲'), -- BroadcastTextID: 43811 - 44064 - 90616 - 112194 - 102129
(125159, @GROUP_ID+0, @ID+0, '艾泽拉斯必将沦陷！', 12, 0, 100, 0, 0, 86699, 132500, '塔尔加西刽子手 to Player'),
(125159, @GROUP_ID+1, @ID+0, '我代表一千个沦陷世界的怒火。', 12, 0, 100, 0, 0, 86704, 132497, '塔尔加西刽子手 to Player'),
(125238, @GROUP_ID+0, @ID+0, '我们来帮你，维伦。', 12, 0, 100, 0, 0, 87740, 134040, '大主教图拉扬 to Player'),
(125239, @GROUP_ID+0, @ID+0, 'Pheta thones gamera。愿圣光指引我们。', 12, 0, 100, 0, 0, 87930, 134041, '先知维伦 to Player'),
(125239, @GROUP_ID+1, @ID+0, '不。该结束了。', 12, 0, 100, 0, 0, 87936, 134055, '先知维伦 to 塔尔加斯'),
(125480, @GROUP_ID+0, @ID+0, '军团战舰来了！隐蔽！', 14, 0, 100, 0, 0, 87019, 135214, '光铸指挥官 to Player'),
(125745, @GROUP_ID+0, @ID+0, '我来自阿古斯，黑暗虚空的力量中心。', 12, 0, 100, 0, 0, 57007, 102124, '复仇征服者 to Player'),
(125745, @GROUP_ID+1, @ID+0, '死在我的力量之下！', 12, 0, 100, 0, 0, 57005, 129828, '复仇征服者 to Player'), -- BroadcastTextID: 129828 - 102122
(125836, @GROUP_ID+0, @ID+0, '去搞清他们的企图……阻止他们的行动。', 14, 0, 100, 1, 0, 87561, 135194, '奥蕾莉亚·风行者 to Player'),
(125840, @GROUP_ID+0, @ID+0, '感谢你们清除我和这根法杖间的障碍，英雄们。', 12, 0, 100, 0, 0, 87825, 135169, '双界行者 to 萨普瑞什的法杖'),
(125921, @GROUP_ID+0, @ID+0, '对，亮晶晶，快给我！', 12, 0, 100, 0, 0, 53431, 137511, '聒噪的恶魔 to Player'), -- BroadcastTextID: 137511 - 99216
(125968, @GROUP_ID+0, @ID+0, '等等……有情况。', 12, 0, 100, 6, 0, 87909, 129973, '先知维伦 to Player'),
(125968, @GROUP_ID+1, @ID+0, '幽灵……都是那一天牺牲的人。', 12, 0, 100, 1, 0, 86759, 129974, '先知维伦 to Player'),
(125968, @GROUP_ID+2, @ID+0, '鲁拉……', 12, 0, 100, 603, 0, 87898, 130106, '先知维伦 to Player'),
(126239, @GROUP_ID+0, @ID+0, '谢谢你，外来者。我们后会有期。', 12, 0, 100, 396, 0, 88176, 135884, '酋长哈顿 to Player'),
(126307, @GROUP_ID+0, @ID+0, '维迪卡尔将成为我们复仇的武器。但不管你选择什么武器，都得在再次投入战斗前彻底了解它。', 12, 0, 100, 1, 0, 87958, 135637, '先知维伦 to Player'),
(126950, @GROUP_ID+0, @ID+0, '圣光啊……他们对我的世界做了什么？', 12, 0, 100, 603, 0, 87902, 135233, '先知维伦 to Player'),
(126954, @GROUP_ID+0, @ID+0, '军团靠攻城火炮集结起了一支大军。伊利丹应该已经到那里去打击他们的阵地了。', 12, 0, 100, 0, 0, 87694, 135223, '大主教图拉扬 to Player'),
(126954, @GROUP_ID+1, @ID+0, '这里是军团的心脏，守卫森严。现在就进攻太过疯狂。我们得多做些准备才能扭转局势。', 12, 0, 100, 0, 0, 88113, 135788, '大主教图拉扬 to Player'),
(127051, @GROUP_ID+0, @ID+0, '他觉得我需要帮助？就为了对付军团？好吧……别掉队。', 12, 0, 100, 0, 0, 87789, 135236, '伊利丹·怒风 to Player'),
(127085, @GROUP_ID+0, @ID+0, '狩猎结束了！你归我了，先知！', 14, 0, 100, 0, 0, 0, 134039, '塔尔加斯 to Player'),
(127085, @GROUP_ID+1, @ID+0, 'Sheet-sah，你还是只会躲在盟友身后。', 12, 0, 100, 0, 0, 87970, 134053, '塔尔加斯 to Player'),
(127085, @GROUP_ID+2, @ID+0, '那我们就改天再——', 12, 0, 100, 0, 0, 87967, 134054, '塔尔加斯 to Player'),
(127085, @GROUP_ID+3, @ID+0, '啊啊啊！', 14, 0, 100, 0, 0, 87973, 131857, '塔尔加斯 to 先知维伦'), -- BroadcastTextID: 33610 - 43779 - 43780 - 59853 - 62791 - 72177 - 33641 - 76981 - 81084 - 83580 - 134057 - 131857 - 129604 - 127507 - 116764 - 102746 - 100754 - 99937 - 99607 - 97447 - 111272 - 103156 - 99937
(127085, @GROUP_ID+4, @ID+0, 'Der''ek……manul……', 12, 0, 100, 0, 0, 87974, 134058, '塔尔加斯 to 先知维伦'),
(127098, @GROUP_ID+0, @ID+0, '湿地蹒跚者陷入了邪能狂怒，摆脱了腐蚀者的控制！', 41, 0, 100, 0, 0, 57004, 136817, '邪怒蹒跚者 to -Unknown-'),
(127732, @GROUP_ID+0, @ID+0, '真是傲慢！你们是在挑战安托兰统帅议会！', 14, 0, 100, 0, 0, 0, 137237, '克罗贝克斯 to Player'),
(128725, @GROUP_ID+0, @ID+0, '玛凯雷……只剩下这些了。', 12, 0, 100, 1, 0, 87899, 135142, '先知维伦 to Player'),
(128725, @GROUP_ID+1, @ID+0, '来吧。我要亲眼看到它。', 12, 0, 100, 397, 0, 87948, 130824, '先知维伦 to Player'),
(128735, @GROUP_ID+0, @ID+0, '没有知识桂冠，我们就无法获胜。', 12, 0, 100, 0, 0, 87949, 131753, '先知维伦 to Player'),
(128735, @GROUP_ID+1, @ID+0, '来吧，我们必须深入黑暗。', 12, 0, 100, 0, 0, 87900, 135240, '先知维伦 to Player'),
(130184, @GROUP_ID+0, @ID+0, '炮手们，集火我标记的目标！', 14, 0, 100, 0, 0, 86984, 134884, '海军上将斯芙拉克丝 to 军团巡洋舰'),
(130185, @GROUP_ID+0, @ID+0, '小心脚下！', 12, 0, 100, 0, 0, 86918, 134889, '首席工程师伊什卡 to 首席工程师伊什卡'), -- BroadcastTextID: 72045 - 134889 - 97676
(130185, @GROUP_ID+1, @ID+0, '据我估算，你们的生存几率为——零！', 12, 0, 100, 0, 0, 86919, 134892, '首席工程师伊什卡 to 首席工程师伊什卡'),
(130185, @GROUP_ID+2, @ID+0, '希望你们喜欢我的发明。', 12, 0, 100, 0, 0, 86917, 134888, '首席工程师伊什卡 to 首席工程师伊什卡'),
(130186, @GROUP_ID+0, @ID+0, '恶魔们！冲锋！', 12, 0, 100, 0, 0, 86983, 134885, '埃洛杜斯将军 to 埃洛杜斯将军'),
(130186, @GROUP_ID+1, @ID+0, '一个不留！', 12, 0, 100, 0, 0, 86984, 134886, '埃洛杜斯将军 to 埃洛杜斯将军'); -- BroadcastTextID: 54497 - 63470 - 76122 - 134886 - 104862 - 94462

