INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(27856, @GROUP_ID+0, @ID+0, '戴上你的头盔。我们要穿越时空啦！', 12, 0, 100, 0, 0, 85371, 131898, '克罗米 to Player'),
(27856, @GROUP_ID+1, @ID+0, '我们又要出发啦！', 12, 0, 100, 0, 0, 85372, 131902, '克罗米 to Player'),
(32638, @GROUP_ID+0, @ID+0, '谢谢你！谢谢你一点忙都不帮！', 12, 0, 100, 6, 0, 0, 33014, '阿古斯的哈克穆德 to Player'),
(32638, @GROUP_ID+1, @ID+0, '哈克穆德没法在这种环境下工作！再见！', 12, 0, 100, 6, 0, 0, 33017, '阿古斯的哈克穆德 to Player'),
(32638, @GROUP_ID+2, @ID+0, '你为什么要这样对待哈克穆德？', 12, 0, 100, 6, 0, 0, 33015, '阿古斯的哈克穆德 to Player'),
(32638, @GROUP_ID+3, @ID+0, '你要把哈克穆德留在这里吗？', 12, 0, 100, 6, 0, 0, 138004, '阿古斯的哈克穆德 to Player'),
(91462, @GROUP_ID+0, @ID+0, '我们的世界之魂很痛苦……', 12, 0, 100, 1, 0, 90799, 139280, '玛法里奥·怒风 to Player'),
(91462, @GROUP_ID+1, @ID+0, '这块水晶……发出了熟悉的声音。', 12, 0, 100, 25, 0, 90779, 139349, '玛法里奥·怒风 to Player'),
(93462, @GROUP_ID+0, @ID+0, '是的。$n在诺森德找到了它。这就是上古之战中达斯雷玛对抗燃烧军团时所用的那把魔法剑。', 12, 0, 100, 1, 0, 0, 110910, '洛拉希尔哨兵 to Player'),
(93508, @GROUP_ID+0, @ID+0, '那是……烈焰之击吗？“那把”烈焰之击？', 12, 0, 100, 6, 0, 0, 110909, '洛拉希尔德鲁伊 to Player'),
(93508, @GROUP_ID+1, @ID+0, '但愿那些法师不会被燃烧军团影响。我们需要他们的帮助。', 12, 0, 100, 1, 0, 0, 110911, '洛拉希尔德鲁伊 to Player'),
(96479, @GROUP_ID+0, @ID+0, '恭祝你春节快乐，并愿你一切顺利，$c。', 12, 0, 100, 3, 0, 0, 49946, '布琳妮 to Player'), -- BroadcastTextID: 49937 - 49942 - 49946
(96990, @GROUP_ID+0, @ID+0, '苹果树注意到了加尼尔，扔给你一只新鲜苹果！', 16, 0, 100, 0, 0, 61694, 101456, '苹果树 to Player'),
(98027, @GROUP_ID+0, @ID+0, '日安，$ct。', 12, 0, 100, 0, 0, 0, 106801, '欢笑的姐妹 to Player'),
(98027, @GROUP_ID+1, @ID+0, '嗨，$ct！', 12, 0, 100, 0, 0, 6515, 106799, '欢笑的姐妹 to Player'), 
(98027, @GROUP_ID+2, @ID+0, '森林中的一切都是那么美妙，$ct。', 12, 0, 100, 0, 0, 0, 106800, '欢笑的姐妹 to Player'),
(98203, @GROUP_ID+0, @ID+0, '后退！它是我的！', 14, 0, 100, 0, 0, 57762, 101906, '伊凡尔 to Player'),
(98203, @GROUP_ID+1, @ID+0, '小偷！法力是我的！', 14, 0, 100, 0, 0, 57765, 101907, '伊凡尔 to Player'), 
(98203, @GROUP_ID+2, @ID+0, '走开！', 14, 0, 100, 0, 0, 57757, 101910, '伊凡尔'), 
(98203, @GROUP_ID+3, @ID+0, '离我的法力远点！', 14, 0, 100, 0, 0, 57758, 101909, '伊凡尔'),
(98203, @GROUP_ID+4, @ID+0, '不……还要……', 14, 0, 100, 0, 0, 57764, 101914, '伊凡尔 to Player'),
(98206, @GROUP_ID+0, @ID+0, '整队，蛆虫们！守住这个缺口，等待古尔丹的命令！', 14, 0, 100, 0, 0, 57770, 105710, '萨卡尔将军 to Player'),
(98206, @GROUP_ID+1, @ID+0, '很好！又有消遣送上门来了！我正闲得发慌呢！', 14, 0, 100, 0, 0, 57772, 105711, '萨卡尔将军 to Player'),
(98206, @GROUP_ID+2, @ID+0, '跟燃烧军团作对的人都得死！', 14, 0, 100, 0, 0, 57773, 105719, '萨卡尔将军'),
(98206, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\Spell_Nature_Earthquake:20|t萨卡尔将军开始施放|cFFF00000|Hspell:197810|h[邪恶重击]|h|r！', 41, 0, 100, 0, 0, 57774, 103571, '萨卡尔将军'),
(98206, @GROUP_ID+4, @ID+0, '在我阴影下的一切都将崩塌！', 14, 0, 100, 0, 0, 57774, 105718, '萨卡尔将军'),
(98206, @GROUP_ID+5, @ID+0, '不……不！没人能击败……伟大的萨卡尔……', 14, 0, 100, 0, 0, 57771, 105713, '萨卡尔将军 to Player'),
(98207, @GROUP_ID+0, @ID+0, '|TINTERFACE\\ICONS\\inv_misc_web_02.blp:20|t纳尔提拉开始施放|cFFF00000|Hspell:200227|h[缠绕之网]|h|r！', 41, 0, 100, 0, 0, 0, 104947, '纳尔提拉'),
(98208, @GROUP_ID+0, @ID+0, '我活了一万年，我是不会死在一群老鼠手里的。', 14, 0, 100, 0, 0, 57783, 105700, '顾问凡多斯 to Player'),
(98208, @GROUP_ID+1, @ID+0, '我是暗夜井宣泄其伟力的载体！我是夜之子！', 14, 0, 100, 0, 0, 57784, 105708, '顾问凡多斯'),
(98208, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\Spell_Holy_BorrowedTime:20|t快在你受到|cFFF00000|Hspell:203935|h[时空迷失]|h|r的影响前重新靠近顾问凡多斯！', 41, 0, 100, 0, 0, 0, 105697, '顾问凡多斯'),
(98208, @GROUP_ID+3, @ID+0, '够了！你们这些小畜生真是太难管教了！', 14, 0, 100, 0, 0, 57786, 105706, '顾问凡多斯 to Player'),
(98208, @GROUP_ID+4, @ID+0, '蝼蚁，你见识过这么狂暴的力量吗？恐怕没有吧？', 14, 0, 100, 0, 0, 57785, 105707, '顾问凡多斯'),
(98208, @GROUP_ID+5, @ID+0, '大魔导师……会砍掉你们的脑袋……', 14, 0, 100, 0, 0, 57782, 105701, '顾问凡多斯 to Player'),
(99560, @GROUP_ID+0, @ID+0, '|TINTERFACE\\ICONS\\trade_archaeology_naarucrystal.blp:20|t$n被囚禁在了|cFFF00000|Hspell:195791|h[隔离区]|h|r内！', 41, 0, 100, 0, 0, 0, 101462, '隔离区 to Player'),
(104921, @GROUP_ID+0, @ID+0, '我的一生中，曾两次见证世界崩裂。我祈求月亮母亲不要让我再见到第三次。', 12, 0, 100, 1, 0, 90800, 139273, '泰兰德·语风 to Player'),
(104921, @GROUP_ID+1, @ID+0, '我感觉这块水晶上有巫术存在。', 12, 0, 100, 1, 0, 90801, 139274, '泰兰德·语风 to Player'),
(107622, @GROUP_ID+0, @ID+0, '别忘了按高级账户的按钮！', 12, 0, 100, 25, 0, 0, 112342, '格鲁托妮雅'),
(107622, @GROUP_ID+1, @ID+0, '看看这些……但愿没有丢什么东西……', 12, 0, 100, 11, 0, 0, 112343, '格鲁托妮雅'),
(107622, @GROUP_ID+2, @ID+0, '如果您丢了东西，请联系客服！呵呵呵……', 12, 0, 100, 22, 0, 0, 112344, '格鲁托妮雅'),
(111060, @GROUP_ID+0, @ID+0, '很高兴见到你，朋友。我可以挡住他们，但我担心很快就会涌过来更多。', 12, 0, 100, 0, 0, 0, 119654, '奥术师纳兰 to Player'),
(111060, @GROUP_ID+1, @ID+0, '元素感应到了这里的骚动。保护好你自己！', 14, 0, 100, 0, 0, 0, 119662, '奥术师纳兰 to Player'),
(111060, @GROUP_ID+2, @ID+0, '这只是个开始。枯法者很快就会被如此庞大的能量吸引过来的。', 12, 0, 100, 0, 0, 0, 119664, '奥术师纳兰 to 法力浮龙'),
(111060, @GROUP_ID+3, @ID+0, '来了！', 14, 0, 100, 0, 0, 0, 119666, '奥术师纳兰 to 法力浮龙'), 
(111060, @GROUP_ID+4, @ID+0, '好险啊。我以为他们不会停下呢。', 12, 0, 100, 0, 0, 0, 119668, '奥术师纳兰 to 枯法魔'),
(111060, @GROUP_ID+5, @ID+0, '什么？！夜之子在攻击我们！', 14, 0, 100, 0, 0, 0, 119669, '奥术师纳兰 to 枯法魔'),
(111060, @GROUP_ID+6, @ID+0, '这是我的最后一点力量了。接受它，去消灭这些叛徒吧！', 14, 0, 100, 0, 0, 0, 119670, '奥术师纳兰 to 枯法魔'),
(111060, @GROUP_ID+7, @ID+0, '这应该是最后一批了。我可以用最后一点力量逃出去。再见了，朋友们。', 12, 0, 100, 0, 0, 0, 119671, '奥术师纳兰 to 夜之子魔剑士'),
(116944, @GROUP_ID+0, @ID+0, '终于落单了。', 14, 0, 100, 0, 0, 82036, 129343, '孟菲斯托斯 to 恐翼蝠'),
(116944, @GROUP_ID+1, @ID+0, '交出圣盾，我就给你们一个痛快！', 14, 0, 100, 0, 0, 80500, 127948, '孟菲斯托斯'),
(116944, @GROUP_ID+2, @ID+0, '我们……才是……最后的赢家……', 14, 0, 100, 0, 0, 80501, 127952, '孟菲斯托斯 to Player'),
(117193, @GROUP_ID+0, @ID+0, '这片古老的土地不属于你们！', 14, 0, 100, 0, 0, 81715, 128811, '阿格洛诺克斯 to Player'),
(117193, @GROUP_ID+1, @ID+0, '这将是你们的最后一口气！', 14, 0, 100, 0, 0, 81712, 128806, '阿格洛诺克斯'),
(117193, @GROUP_ID+2, @ID+0, '我的末日……已刻在……轮回中……', 14, 0, 100, 0, 0, 81722, 128818, '阿格洛诺克斯 to Player'),
(117194, @GROUP_ID+0, @ID+0, '失败者才看书！', 14, 0, 100, 0, 0, 81842, 128827, '轻蔑的萨什比特 to Player'),
(117194, @GROUP_ID+1, @ID+0, '过来打啊！', 14, 0, 100, 0, 0, 81840, 128825, '轻蔑的萨什比特'),
(117194, @GROUP_ID+2, @ID+0, '我没认真……想过……', 14, 0, 100, 0, 0, 81847, 128832, '轻蔑的萨什比特 to Player'),
(118705, @GROUP_ID+0, @ID+0, '来吧，孩子们，吃吧！', 14, 0, 100, 0, 0, 0, 128858, '纳尔莎'),
(118705, @GROUP_ID+1, @ID+0, '开饭了！', 14, 0, 100, 0, 0, 0, 25745, '纳尔莎'), -- BroadcastTextID: 20813 - 25745
(118719, @GROUP_ID+0, @ID+0, '他们战胜了萨什比特？！快跑！！！', 14, 0, 100, 0, 0, 0, 130703, '虫语清道夫 to 鬼火小鬼'),
(118723, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\ABILITY_WARLOCK_SOULSWAP.BLP:20|t转身避开加泽拉克斯的|cFFFF0000|Hspell:239217|h[眩目闪光]|h|r！', 41, 0, 100, 0, 0, 0, 130806, '加泽拉克斯'),
