(122663, @GROUP_ID+5, @ID+0, '时间耗尽了。', 42, 0, 100, 0, 0, 0, 133442, '克罗米 to Player'),
(122663, @GROUP_ID+6, @ID+0, '也许下次吧……', 14, 0, 100, 0, 0, 85314, 132032, '克罗米 to Player'),
(122663, @GROUP_ID+7, @ID+0, '记住，那个萨特就在水边的骨爪里。我们去干掉他吧！', 12, 0, 100, 0, 0, 85338, 131944, '克罗米 to Player'),
(122663, @GROUP_ID+8, @ID+0, '耶！我做到了！', 12, 0, 100, 0, 0, 85352, 132030, '克罗米 to 翡翠天爪枭'),
(122663, @GROUP_ID+9, @ID+0, '抱歉，但……这是注定的！', 12, 0, 100, 0, 0, 85350, 132028, '克罗米 to 翡翠天爪枭'),
(122663, @GROUP_ID+10, @ID+0, '奇怪。我不记得自己跟萨特有过冲突，不管是现在还是未来。', 12, 0, 100, 0, 0, 85339, 131945, '克罗米 to 萨拉斯·维索恩'),
(122663, @GROUP_ID+11, @ID+0, '抱歉……', 14, 0, 100, 0, 0, 85317, 96670, '克罗米 to Player'),
(122875, @GROUP_ID+0, @ID+0, '你扭曲时光的好日子到头了，小龙崽子！', 12, 0, 100, 0, 0, 0, 133233, '萨拉斯·维索恩 to Player'),
(124104, @GROUP_ID+0, @ID+0, '干掉那头龙崽子！为了部落！', 12, 0, 100, 0, 0, 0, 133237, '妖术师贾昆达 to Player'),
(124158, @GROUP_ID+0, @ID+0, '结束了，凡人。你们的脑袋值一大笔赏金，我就是为此而来的。', 14, 0, 100, 0, 0, 86522, 134868, '猎魂者伊墨纳尔 to Player'),
(124158, @GROUP_ID+1, @ID+0, '你们的骨头会帮我大赚一笔的。', 14, 0, 100, 0, 0, 86524, 134780, '猎魂者伊墨纳尔 to Player'),
(124158, @GROUP_ID+2, @ID+0, '做个好梦。', 14, 0, 100, 0, 0, 86379, 134402, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\SPELL_NATURE_SLEEP:20|t%s用|cFFFF0000|Hspell:254244|h[催眠气罐]|h|r瞄准了你！', 42, 0, 100, 0, 0, 0, 137717, '猎魂者伊墨纳尔 to Player'),
(124158, @GROUP_ID+4, @ID+0, '我待会儿再来对付你。', 14, 0, 100, 0, 0, 86381, 134404, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+5, @ID+0, '有本事的话，就跟上吧！', 14, 0, 100, 0, 0, 86385, 134405, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+6, @ID+0, '能够证明身份的部分可得保持完整。', 14, 0, 100, 0, 0, 86374, 134409, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+7, @ID+0, '你们无处可逃了。', 14, 0, 100, 0, 0, 86375, 134440, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+8, @ID+0, '能活到现在，你们已经赚了。', 14, 0, 100, 0, 0, 86389, 134459, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+9, @ID+0, '向我的位置开火！', 14, 0, 100, 0, 0, 86377, 134455, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+10, @ID+0, '轰炸本区域！', 14, 0, 100, 0, 0, 86378, 134456, '猎魂者伊墨纳尔'),
(124158, @GROUP_ID+11, @ID+0, '我真后悔……接了……这个活儿……', 14, 0, 100, 0, 0, 86384, 133864, '猎魂者伊墨纳尔 to Player'),
(124828, @GROUP_ID+0, @ID+0, '主人要你们死！', 14, 0, 100, 0, 0, 88242, 135985, '寂灭者阿古斯'),
(124828, @GROUP_ID+1, @ID+0, '没有希望。只有痛苦。痛苦！', 14, 0, 100, 0, 0, 88244, 135987, '寂灭者阿古斯 to 寂灭者阿古斯'),
(124828, @GROUP_ID+2, @ID+0, '结束这一切吧！', 14, 0, 100, 0, 0, 88239, 135897, '寂灭者阿古斯 to 寂灭者阿古斯'), -- BroadcastTextID: 33871 - 135897
/*
(124828, @GROUP_ID+3, @ID+0, '寂灭者阿古斯正在部署重组模块！', 41, 0, 100, 0, 0, 0, UNKNOWN, '寂灭者阿古斯 to 寂灭者阿古斯'),
*/
(124913, @GROUP_ID+0, @ID+0, '小心！凡人是不能走织梦者的道路的！', 14, 0, 100, 0, 0, 88494, 136088, '麦格尼·铜须 to 蒂玛，幽影之母'),
(124913, @GROUP_ID+1, @ID+0, '那个女巫在用高戈奈斯的风暴攻击你们！', 14, 0, 100, 0, 0, 88490, 136090, '麦格尼·铜须 to 蒂玛，幽影之母'),
(124913, @GROUP_ID+2, @ID+0, '那女巫对众神之父的折磨已经化为了实体！', 14, 0, 100, 0, 0, 88488, 136091, '麦格尼·铜须 to 诺拉，烈焰之母'),
(124913, @GROUP_ID+3, @ID+0, '恶魔在用塑造者的烈焰对付你们！', 14, 0, 100, 0, 0, 86927, 136089, '麦格尼·铜须 to 诺拉，烈焰之母');
/*
(125885, @GROUP_ID+0, @ID+0, '海洋和天空之力能帮助这些勇士，高戈奈斯！', 14, 0, 100, 0, 0, 90889, UNKNOWN, '阿曼苏尔 to 高戈奈斯'),
(125885, @GROUP_ID+1, @ID+0, '让大海的怒涛洗刷这腐蚀吧！', 14, 0, 100, 0, 0, 90890, UNKNOWN, '阿曼苏尔 to 高戈奈斯'),
(125885, @GROUP_ID+2, @ID+0, '阿格拉玛！将你的力量赐予这些凡人吧，兄弟。', 14, 0, 100, 0, 0, 90886, UNKNOWN, '阿曼苏尔 to 阿曼苏尔'),
(125885, @GROUP_ID+3, @ID+0, '我掌握着时间之力，寂灭者！它能束缚你冷酷的怒火！', 14, 0, 100, 0, 0, 90898, UNKNOWN, '阿曼苏尔 to 寂灭者阿古斯'),
(126268, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\Shaman_PVP_RipplingWaters:20|t%s开始施放|cFFFF0000|Hspell:255594|h[海天之力]|h|r！', 41, 0, 100, 0, 0, 90889, UNKNOWN, '高戈奈斯 to 高戈奈斯');
