(123743, @GROUP_ID+0, @ID+0, '勇士们！这边！', 14, 0, 100, 0, 0, 87562, 133381, '奥蕾莉亚·风行者 to Player'),
(123743, @GROUP_ID+1, @ID+0, '跟我走！', 14, 0, 100, 0, 0, 87563, 135522, '奥蕾莉亚·风行者 to Player'),
(124276, @GROUP_ID+0, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空之门出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133029, 'Conversation Controller to Player'),
(124276, @GROUP_ID+1, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t破碎遗迹出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133028, 'Conversation Controller to Player'),
(124276, @GROUP_ID+2, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t下层虚空裂口出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133031, 'Conversation Controller to Player');

INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(124276, @GROUP_ID+3, @ID+0, '|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t神殿基座出现了一条虚空裂缝！', 42, 0, 100, 0, 0, 0, 133033, 'Conversation Controller to Player'),
(124511, @GROUP_ID+0, @ID+0, '我自由了！', 14, 0, 100, 0, 0, 87805, 132206, '大审判官拉尔加 to Player'), -- BroadcastTextID: 35570 - 35570 - 46400 - 80171 - 81599 - 80171 - 81599 - 132206 - 125533 - 106886 - 95093 - 132206 - 125533 - 106886 - 95093
(124511, @GROUP_ID+1, @ID+0, '拉扎鲁恩，我的仆人。留下来，干掉这些蠢货。我还有事要做。', 12, 0, 100, 0, 0, 87800, 133358, '大审判官拉尔加 to Player'),
(124745, @GROUP_ID+0, @ID+0, '|TInterface\\ICONS\\SPELL_SHADOW_PAINSPIKE:20|t一名大型裂隙守护者开始施放|cFFFF0000|Hspell:245164|h[绝望碎片]|h|r！', 42, 0, 100, 0, 0, 0, 135144, '大型裂隙守护者 to Player'),
(125099, @GROUP_ID+0, @ID+0, '吸干传送门能量！纳鲁的弱点能成为你的力量！', 14, 0, 100, 0, 0, 88268, 133972, '双界行者 to 奥蕾莉亚·风行者'),
(125099, @GROUP_ID+1, @ID+0, '夺取传送门力量，奥蕾莉亚！它能成为你的武器！', 14, 0, 100, 0, 0, 88269, 132304, '双界行者 to 奥蕾莉亚·风行者'),
(125836, @GROUP_ID+0, @ID+0, '去搞清他们的企图……阻止他们的行动。', 14, 0, 100, 1, 0, 87561, 135194, '奥蕾莉亚·风行者 to Player'),
(125840, @GROUP_ID+0, @ID+0, '感谢你们清除我和这根法杖间的障碍，英雄们。', 12, 0, 100, 0, 0, 87825, 135169, '双界行者 to 萨普瑞什的法杖'),
(126765, @GROUP_ID+0, @ID+0, '向我敞开灵魂吧。', 12, 0, 100, 0, 0, 86682, 132516, '纳斯拉克森织魂者 to Player'),
(126765, @GROUP_ID+1, @ID+0, '混沌统治一切。', 12, 0, 100, 0, 0, 86684, 132517, '纳斯拉克森织魂者 to 光铸战争机甲');
