INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(98542, @GROUP_ID+0, @ID+0, '消灭！吞噬！', 14, 0, 100, 0, 0, 54518, 100957, '融合之魂'),
(98542, @GROUP_ID+1, @ID+0, '收割时间到！', 14, 0, 100, 0, 0, 54516, 100995, '融合之魂 to Player'),
(98542, @GROUP_ID+2, @ID+0, '离开这个微不足道的躯壳，加入我们的行列……', 14, 0, 100, 0, 0, 54564, 100994, '融合之魂 to Player'),
(98542, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\spell_warlock_demonsoul:20|t你受到了|cFFFF0000|Hspell:194960|h[灵魂回响]|h|r的影响！', 42, 0, 100, 0, 0, 0, 103698, '融合之魂 to Player'),
(98542, @GROUP_ID+4, @ID+0, '黑鸦堡垒的古代幽灵，来加入合唱吧！', 14, 0, 100, 0, 0, 54563, 100997, '融合之魂'),
(98542, @GROUP_ID+5, @ID+0, '我要享用你的精华……', 14, 0, 100, 0, 0, 54522, 100993, '融合之魂'),
(98542, @GROUP_ID+6, @ID+0, '这……这力量……太强大了！', 14, 0, 100, 0, 0, 54522, 100998, '融合之魂 to 融合之魂'),
(98696, @GROUP_ID+0, @ID+0, '你们将葬身此地，蠢货。', 14, 0, 100, 0, 0, 54515, 101132, '伊莉萨娜·拉文凯斯'),
(98696, @GROUP_ID+1, @ID+0, '你无路可逃了。', 14, 0, 100, 0, 0, 54561, 101194, '伊莉萨娜·拉文凯斯 to Player'),
(98696, @GROUP_ID+2, @ID+0, '狩猎不会结束……', 14, 0, 100, 0, 0, 54513, 101208, '伊莉萨娜·拉文凯斯'),
(98696, @GROUP_ID+3, @ID+0, '不！我现在明白了……背……叛……', 14, 0, 100, 0, 0, 54514, 101221, '伊莉萨娜·拉文凯斯 to Player'),
(98706, @GROUP_ID+0, @ID+0, '兄弟姐妹们，入侵者冲我们来了。击退他们！进攻！', 14, 0, 100, 0, 0, 0, 106226, '指挥官什达索尼 to 复活的弓箭手'),
(98792, @GROUP_ID+0, @ID+0, '哈！我们会用这些大石头解决他们的！', 14, 0, 100, 0, 0, 0, 120216, '虫语清道夫 to Player'),
(98792, @GROUP_ID+1, @ID+0, '啊！他们来了！快跑！', 14, 0, 100, 0, 0, 0, 120215, '虫语清道夫 to Player'),
(98792, @GROUP_ID+2, @ID+0, '呃……噢……哇啊啊啊！！！！', 14, 0, 100, 0, 0, 0, 104234, '虫语清道夫 to Player'),
(98792, @GROUP_ID+3, @ID+0, '啊！我们很抱歉！我们保证！', 14, 0, 100, 0, 0, 0, 120218, '虫语清道夫 to Player'),
(98810, @GROUP_ID+0, @ID+0, '%s变得狂怒无比！', 16, 0, 100, 0, 0, 0, 10677, '愤怒卫士剑圣'), -- BroadcastTextID: 1191 - 10645 - 10677
(98949, @GROUP_ID+0, @ID+0, '用你们的鲜血染红城堡！', 14, 0, 100, 0, 0, 54504, 101266, '可恨的斯麦斯帕'),
(98949, @GROUP_ID+1, @ID+0, '别费劲逃跑了，跳蚤……', 14, 0, 100, 0, 0, 54506, 101273, '可恨的斯麦斯帕 to Player'),
(98949, @GROUP_ID+2, @ID+0, '哈！抓住你了！', 14, 0, 100, 0, 0, 54503, 101274, '可恨的斯麦斯帕'), -- BroadcastTextID: 101274 - 94218
(98949, @GROUP_ID+3, @ID+0, '在我脚下颤栗吧。', 14, 0, 100, 0, 0, 54501, 101272, '可恨的斯麦斯帕'),
(98949, @GROUP_ID+4, @ID+0, '但是……我不可能……输……', 14, 0, 100, 0, 0, 54636, 101278, '可恨的斯麦斯帕 to Player'),
(98965, @GROUP_ID+0, @ID+0, '恶魔，你们休想占据这个世界！', 14, 0, 100, 0, 0, 54536, 101281, '库塔洛斯·拉文凯斯'),
(98970, @GROUP_ID+0, @ID+0, '现在，睡吧……', 14, 0, 100, 0, 0, 54499, 101289, '丹塔利纳克斯'),
(99857, @GROUP_ID+0, @ID+0, '我……现在明白了。你……你必须找到库塔洛斯。你必须阻止这一切。', 12, 0, 100, 0, 0, 54558, 101007, '艾瑟德林·拉文凯斯领主 to Player');

