INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(50047, 'zhCN', '免费样品', '收集$1oa个神秘矿石样本。', '王室命令军情七处渗透进地精采掘工程并收集情报，让我们了解这种崭新神秘物质。\n\n我的特工已经渗透了营地，但时间有限，我们必须快点拿到一些提取出来的矿物的样品。\n\n也就是说，我需要找人进行直接行动。那个人要能返回', '', '', '', '', '', '', 26124),
(50046, 'zhCN', '放置炸弹', '有人搞破坏放置$1oa个炸药', '部落一直在争分夺秒地从巨大的伤口中抽取这种神秘物质，真是不知羞耻。\n\n幸好，地精工程学远远没有我们在诺莫瑞根做的东西复杂。只需要一点传统的炸药，就能彻底摧毁一台地精切割机。\n\n多单纯的机器啊！\n\n拿上这些炸药包，放在矿工营地周围还没启动的切割机上。\n\n那些贪婪的地精得花好几周才能找到备用机器重新开工！', '', '', '', '', '', '', 26124);


