INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(94960, @GROUP_ID+0, @ID+0, '我才是审判者。', 14, 0, 100, 0, 0, 54651, 102956, '海姆达尔'),
(94960, @GROUP_ID+1, @ID+0, '龙骑兵！靠近我！', 14, 0, 100, 0, 0, 54641, 102944, '海姆达尔'),
(94960, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\INV_Misc_Horn_03:20|t海姆达尔吹响|cFFFF0404|Hspell:191284|h[勇气号角]|h|r召唤风暴幼龙！', 41, 0, 100, 0, 0, 54641, 104163, '海姆达尔'),
(94960, @GROUP_ID+3, @ID+0, '无能者必将血洒圣殿！', 14, 0, 100, 0, 0, 54640, 102943, '海姆达尔'),
(94960, @GROUP_ID+4, @ID+0, '精彩的战斗！你们可以继续前进了。', 14, 0, 100, 0, 0, 54648, 102951, '海姆达尔'),
(95674, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\spell_hunter_lonewolf:20|t芬雷尔开始施放|cFFFF0404|Hspell:196543|h[挫志嚎叫]|h|r！', 41, 0, 100, 0, 0, 0, 104038, '芬雷尔'),
(95674, @GROUP_ID+1, @ID+0, '受伤的芬雷尔逃回他的巢穴去了。', 41, 0, 100, 0, 0, 0, 104029, '芬雷尔'),
(95675, @GROUP_ID+0, @ID+0, '放弃圣盾，否则就死！', 14, 0, 100, 0, 0, 54614, 102921, '神王斯科瓦尔德'),
(95675, @GROUP_ID+1, @ID+0, '你将痛苦地死去！', 14, 0, 100, 0, 0, 54630, 102937, '神王斯科瓦尔德'),
(95675, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\Spell_Fire_FelFlameRing:20|t斯科瓦尔德开始施放|cFFFF0404|Hspell:193826|h[诸神黄昏]|h|r！', 41, 0, 100, 0, 0, 54630, 106469, '神王斯科瓦尔德'),
(95675, @GROUP_ID+3, @ID+0, '我所有的计划……都完了……', 14, 0, 100, 0, 0, 54620, 102927, '神王斯科瓦尔德 to Player'),
(95676, @GROUP_ID+0, @ID+0, '战利品属于胜利者……阿格拉玛之盾是你们的了。', 14, 0, 100, 0, 0, 54569, 100240, '奥丁 to 布约恩国王'),
(95676, @GROUP_ID+1, @ID+0, '真了不起！没想到还有人能对抗瓦拉加尔的力量……而他们就站在我面前。', 14, 0, 100, 0, 0, 54584, 102879, '奥丁 to 奥丁'),
(95676, @GROUP_ID+2, @ID+0, '最后的试炼将由我主持。只要战胜我，我就亲手把你们的名字刻在这座圣殿里，并送上勇士应得的奖励。', 14, 0, 100, 0, 0, 54583, 102881, '奥丁 to 奥丁'),
(95676, @GROUP_ID+3, @ID+0, '我好久没遇到过像样的对手了。来战斗吧！', 14, 0, 100, 0, 0, 54604, 102913, '奥丁'),
(95676, @GROUP_ID+4, @ID+0, '够了！我……认输！你们真是了不起。我说过，你们会得到应得的奖赏。', 12, 0, 100, 0, 0, 54598, 102907, '奥丁'),
(95833, @GROUP_ID+0, @ID+0, '我不会让你失望的，艾尔！', 14, 0, 100, 0, 0, 54687, 102993, '赫娅'),
(95833, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t赫娅开始施放|cFFFF0404|Hspell:192206|h[圣洁庇护]|h|r！', 41, 0, 100, 0, 0, 0, 122900, '赫娅'),
(95833, @GROUP_ID+2, @ID+0, '你休想继续玷污这座殿堂！', 14, 0, 100, 0, 0, 54681, 102986, '赫娅'),
(95833, @GROUP_ID+3, @ID+0, '对不起，艾尔……我让你失望了……', 14, 0, 100, 0, 0, 54681, 102987, '赫娅 to Player'),
(95843, @GROUP_ID+0, @ID+0, '我会好好享受碾压你们的快感的！', 14, 0, 100, 0, 0, 54577, 102583, '赫尔多国王 to 赫尔多国王'),
(95843, @GROUP_ID+1, @ID+0, '我的力量……消散了。', 14, 0, 100, 0, 0, 54575, 102585, '赫尔多国王 to Player'),
(97081, @GROUP_ID+0, @ID+0, '他们的失败就是我们的胜利！', 14, 0, 100, 0, 0, 54570, 102590, '布约恩国王'),
(97081, @GROUP_ID+1, @ID+0, '你们……击败了我。', 14, 0, 100, 0, 0, 54569, 102592, '布约恩国王 to Player'),
(97083, @GROUP_ID+0, @ID+0, '你们痛苦的哀嚎将永世回荡！', 14, 0, 100, 0, 0, 54574, 102586, '拉努夫国王 to 拉努夫国王'),
(97083, @GROUP_ID+1, @ID+0, '我拥抱深渊！', 14, 0, 100, 0, 0, 54572, 102588, '拉努夫国王 to Player'),
(97084, @GROUP_ID+0, @ID+0, '看来我……低估了你们。', 14, 0, 100, 0, 0, 54578, 102582, '托尔国王 to Player'),
(97202, @GROUP_ID+0, @ID+0, '你休想妨碍赫娅的晋升！', 14, 0, 100, 0, 0, 54670, 102975, '启迪者奥米尔'),
(97202, @GROUP_ID+1, @ID+0, '愿圣光永远照耀你，赫娅！', 14, 0, 100, 0, 0, 54671, 102976, '启迪者奥米尔 to Player'),
(97219, @GROUP_ID+0, @ID+0, '你们的存在玷污了这场仪式，凡人！', 14, 0, 100, 0, 0, 54672, 102977, '索斯坦'),
(97219, @GROUP_ID+1, @ID+0, '赫娅……你来执掌风暴的怒火！', 14, 0, 100, 0, 0, 54673, 102978, '索斯坦 to Player');

