INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(95885, @GROUP_ID+0, @ID+0, '重返战场，感觉真不错。', 14, 0, 100, 0, 0, 55406, 97634, '提拉宋·萨瑟利尔'),
(95885, @GROUP_ID+1, @ID+0, '双刃渴望鲜血。', 14, 0, 100, 0, 0, 55416, 97641, '提拉宋·萨瑟利尔'),
(95885, @GROUP_ID+2, @ID+0, '我的力量……还不够吗？', 14, 0, 100, 0, 0, 55408, 97650, '提拉宋·萨瑟利尔 to Player'),
(95886, @GROUP_ID+0, @ID+0, '如此……漫长……炎魔之王呢？他为何不回应我的呼唤？', 14, 0, 100, 0, 0, 55437, 97655, '阿什高姆'),
(95886, @GROUP_ID+1, @ID+0, '灰飞烟灭，魂飞魄散吧。', 14, 0, 100, 0, 0, 55433, 97659, '阿什高姆'),
(95886, @GROUP_ID+2, @ID+0, '火……熄灭了。', 14, 0, 100, 0, 0, 55426, 97667, '阿什高姆 to Player'),
(95887, @GROUP_ID+0, @ID+0, '有客人？太好了！', 14, 0, 100, 0, 0, 55424, 97672, '格雷泽'),
(95887, @GROUP_ID+1, @ID+0, '如果我能看见未来就……', 14, 0, 100, 0, 0, 55474, 97684, '格雷泽 to 有橙'),
(95888, @GROUP_ID+0, @ID+0, '那好吧。我要杀光你们。', 14, 0, 100, 0, 0, 55472, 97689, '科达娜·邪歌'),
(95888, @GROUP_ID+1, @ID+0, '暗夜精灵都该学会热爱黑暗。', 14, 0, 100, 0, 0, 55463, 97699, '科达娜·邪歌'),
(95888, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\Ability_Rogue_Shadowstep:20|t%s使用|cFFFF0000|Hspell:197823|h[暗影步]|h|r脱离了队伍，快使用艾露恩之光让她现形！', 41, 0, 100, 0, 0, 0, 103279, '科达娜·邪歌'),
(95888, @GROUP_ID+3, @ID+0, '我是不可阻挡的！我奋斗多年，承受无数痛苦。胜利必将属于我！', 14, 0, 100, 0, 0, 55461, 97701, '科达娜·邪歌 to 科达娜·邪歌'),
(95888, @GROUP_ID+4, @ID+0, '|TInterface\\Icons\\ability_priest_auspiciousspirits:20|t平台周围的阴影中出现大量幽灵！', 41, 0, 100, 0, 0, 0, 103280, '科达娜·邪歌'),
(95888, @GROUP_ID+5, @ID+0, '加入军团令我的力量暴涨。让我来展示一下吧。', 14, 0, 100, 0, 0, 55462, 97700, '科达娜·邪歌'),
(95888, @GROUP_ID+6, @ID+0, '我输了？怎么可能！你……一无是处……', 14, 0, 100, 0, 0, 55460, 97702, '科达娜·邪歌 to Player'),
(96015, @GROUP_ID+0, @ID+0, '噢……新的审判对象。', 14, 0, 100, 0, 0, 64824, 97707, '审判官托蒙托鲁姆'),
(96015, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\Spell_Shadow_Teleport:20|t%s|cFFFF0000|Hspell:200898|h[传送]|h|r到附近的牢房并开始释放囚犯！', 41, 0, 100, 0, 0, 0, 105573, '审判官托蒙托鲁姆'),
(96015, @GROUP_ID+2, @ID+0, '看看门牌号背后是什么……', 14, 0, 100, 0, 0, 64827, 97710, '审判官托蒙托鲁姆'),
(96015, @GROUP_ID+3, @ID+0, '你们的灵魂归我了。', 14, 0, 100, 0, 0, 64828, 97711, '审判官托蒙托鲁姆'), 
(96015, @GROUP_ID+4, @ID+0, '真让人失望。', 14, 0, 100, 0, 0, 64829, 97712, '审判官托蒙托鲁姆 to Player'),
(96657, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n|cFFFF0000|Hspell:185828|h[复燃]|h|r了一个邪能烧灼者！', 16, 0, 100, 0, 0, 0, 96139, '刃舞者伊莲娜 to 刃舞者伊莲娜'),
(99013, @GROUP_ID+0, @ID+0, '感谢你的帮助。你出手救了我的命。', 12, 0, 100, 0, 0, 55443, 103226, '德兰妮·语风 to Player'),
(99013, @GROUP_ID+1, @ID+0, '如果你继续深入的话，就会发现这里还潜伏着更可怕的东西。', 12, 0, 100, 0, 0, 55442, 103227, '德兰妮·语风 to Player'),
(99240, @GROUP_ID+0, @ID+0, '房间内的反制机关已启动。', 16, 0, 100, 0, 0, 55437, 106822, '反制机关 to 阿什高姆'),
(102583, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n死亡时发生了|cFFFF0000|Hspell:202663|h[自爆]|h|r！', 16, 0, 100, 0, 0, 0, 122413, '邪能烧灼者 to 邪能烧灼者'),
(103860, @GROUP_ID+0, @ID+0, '叛徒完蛋了。谢谢你，我们欠你一个大人情。', 12, 0, 100, 16, 0, 55441, 103228, '德兰妮·语风'),
(103860, @GROUP_ID+1, @ID+0, '我可以自己返回地面；但你必须将今天的事告诉其他守望者。', 12, 0, 100, 0, 0, 55440, 103229, '德兰妮·语风');

