INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(91784, @GROUP_ID+0, @ID+0, '哼。入侵者。他们走不了多远。', 14, 0, 100, 0, 0, 54193, 101992, '督军帕杰什 to Player'),
(91784, @GROUP_ID+1, @ID+0, '啊，又是你，废物。现在只剩你我……还有我的卫兵了！', 14, 0, 100, 0, 0, 54181, 99890, '督军帕杰什 to Player'),
(91784, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\Spell_Shadow_UnholyFrenzy:20|t督军帕杰什被|cFFFF0000|Hspell:197064|h[激怒]|h|r了！', 41, 0, 100, 0, 0, 0, 101804, '督军帕杰什'),
(91784, @GROUP_ID+3, @ID+0, '你休想阻挡……风暴……', 14, 0, 100, 0, 0, 54182, 99894, '督军帕杰什 to Player'),
(91789, @GROUP_ID+0, @ID+0, '看来这儿有虫子……', 14, 0, 100, 0, 0, 56655, 104580, '积怨夫人 to Player'),
(91789, @GROUP_ID+1, @ID+0, '继续仪式！我来解决这些蠢货！', 14, 0, 100, 0, 0, 54194, 100227, '积怨夫人 to Player'),
(91789, @GROUP_ID+2, @ID+0, '炸焦你们，旱鸭子！', 14, 0, 100, 0, 0, 54200, 100235, '积怨夫人'),
(91789, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\Spell_Shaman_StaticShock:20|t%s开始引爆|cFFFF0000|Hspell:193597|h[静电新星]|h|r。快离开水域！', 41, 0, 100, 0, 0, 54200, 100243, '积怨夫人'),
(91789, @GROUP_ID+4, @ID+0, '|TInterface\\Icons\\Spell_Frost_SummonWaterElemental:20|t%s开始施放|cFFFF0000|Hspell:193682|h[召唤风暴]|h|r！', 41, 0, 100, 0, 0, 0, 100238, '积怨夫人'),
(91789, @GROUP_ID+5, @ID+0, '涨潮了……', 14, 0, 100, 0, 0, 54204, 100237, '积怨夫人'),
(91789, @GROUP_ID+6, @ID+0, '风暴正在汇聚……', 14, 0, 100, 0, 0, 54203, 100245, '积怨夫人'),
(91789, @GROUP_ID+7, @ID+0, '感觉到凉风了吗？它们来了……', 14, 0, 100, 0, 0, 54195, 100228, '积怨夫人 to Player'),
(91797, @GROUP_ID+0, @ID+0, '让海浪淹死你们这些可怜虫！', 14, 0, 100, 0, 0, 54316, 102315, '深须国王 to Player'),
(91797, @GROUP_ID+1, @ID+0, '我很好奇，你们能憋多久呢？', 14, 0, 100, 0, 0, 54312, 102305, '深须国王'),
(91797, @GROUP_ID+2, @ID+0, '地震是巨浪的先锋！', 14, 0, 100, 0, 0, 54314, 102307, '深须国王'),
(91797, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\spell_frost_summonwaterelemental:20|t%s开始施放|cFFFF0000|Hspell:193051|h[呼潮引浪]|h|r！', 41, 0, 100, 0, 0, 54164, 99824, '深须国王'),
(91797, @GROUP_ID+4, @ID+0, '让大海卷走你！', 14, 0, 100, 0, 0, 54164, 102302, '深须国王'),
(91797, @GROUP_ID+5, @ID+0, '%s变得愤怒了！', 16, 0, 100, 0, 0, 0, 24144, '深须国王'), -- BroadcastTextID: 2384 - 7798 - 24144
(91797, @GROUP_ID+6, @ID+0, '你们还没赢呢。她就要到了……', 14, 0, 100, 0, 0, 54318, 102311, '深须国王 to Player'),
(91808, @GROUP_ID+0, @ID+0, '|TInterface\\Icons\\ability_rogue_venomouswounds:20|t你受到了|cFFFF0000|Hspell:191855|h[剧毒创伤]|h|r的影响！', 42, 0, 100, 0, 0, 0, 98862, '瑟芬崔斯克 to Player'),
(91808, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\inv_misc_volatilewater:20|t%s开始|cFFFF0000|Hspell:191873|h[下潜]|h|r！', 41, 0, 100, 0, 0, 0, 99006, '瑟芬崔斯克'),
(96028, @GROUP_ID+0, @ID+0, '风暴已经苏醒。', 14, 0, 100, 0, 0, 54318, 99950, '艾萨拉之怒'),
(96028, @GROUP_ID+1, @ID+0, '涨潮了！', 14, 0, 100, 0, 0, 54207, 100046, '艾萨拉之怒 to Player'),
(96028, @GROUP_ID+2, @ID+0, '毁灭万物！', 14, 0, 100, 0, 0, 54205, 99943, '艾萨拉之怒 to Player'),
(96028, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\inv_misc_herb_stormvine:20|t%s开始发出|cFFFF0000|Hspell:192985|h[愤怒嚎叫]|h|r！', 41, 0, 100, 0, 0, 54208, 106737, '艾萨拉之怒'), -- BroadcastTextID: 106737 - 106736
(96028, @GROUP_ID+4, @ID+0, '风暴！', 14, 0, 100, 0, 0, 54208, 76941, '艾萨拉之怒'),
(96028, @GROUP_ID+5, @ID+0, '水……永恒……', 14, 0, 100, 0, 0, 54206, 99944, '艾萨拉之怒 to Player'),
(97171, @GROUP_ID+0, @ID+0, '护盾被削弱了！', 14, 0, 100, 0, 0, 0, 104567, '积怨奥术师 to Player'),
(97171, @GROUP_ID+1, @ID+0, '积怨夫人是无敌的！她是不会倒下的！', 14, 0, 100, 0, 0, 0, 104568, '积怨奥术师 to Player'),
(98173, @GROUP_ID+0, @ID+0, '我们还需要一点时间！', 14, 0, 100, 0, 0, 54207, 100045, '秘术师萨维 to Player'),
(100216, @GROUP_ID+0, @ID+0, '来了一群旱鸭子！我们要用盐和鳞片把他们赶回去！', 14, 0, 100, 0, 0, 0, 104346, '积怨牧鱼者 to Player'),
(100248, @GROUP_ID+0, @ID+0, '不！仪式还没有完成！', 14, 0, 100, 0, 0, 0, 100040, '祭祀者勒莎 to Player'),
(100249, @GROUP_ID+0, @ID+0, '束缚之力减弱了……', 14, 0, 100, 0, 0, 0, 100041, '导魔者瓦里兹 to Player'),
(100250, @GROUP_ID+0, @ID+0, '它还在成型！', 14, 0, 100, 0, 0, 0, 100042, '束缚者阿什奥伊 to Player');

