(91003, @GROUP_ID+0, @ID+0, '巨石粉碎！', 14, 0, 100, 0, 0, 54551, 102714, '洛克莫拉'),
(91003, @GROUP_ID+1, @ID+0, '洛克莫拉生成了|cFFFF0000|Hspell:215898|h[晶化之地]|h|r！不要移动！', 41, 0, 100, 0, 0, 0, 114681, '洛克莫拉'),
(91003, @GROUP_ID+2, @ID+0, '洛克莫拉后仰，准备施放|cFFFF0000|Hspell:188169|h[剃刀碎片]|h|r！', 41, 0, 100, 0, 0, 0, 108748, '洛克莫拉 to Player'),
(91003, @GROUP_ID+3, @ID+0, '洛克……不会……碎的……', 14, 0, 100, 0, 0, 54549, 102713, '洛克莫拉 to Player'),
(91004, @GROUP_ID+0, @ID+0, '看着，纳瓦罗格，看你的英雄们是怎么死的。', 14, 0, 100, 0, 0, 54704, 103031, '乌拉罗格·塑山'),
(91004, @GROUP_ID+1, @ID+0, '乌拉罗格进入了|cFFFF0000|Hspell:198510|h[山峰形态]|h|r！', 41, 0, 100, 0, 0, 0, 108725, '乌拉罗格·塑山'),
(91004, @GROUP_ID+2, @ID+0, '这就是四分五裂的感觉吗……', 14, 0, 100, 0, 0, 54703, 103028, '乌拉罗格·塑山 to Player'),
(91005, @GROUP_ID+0, @ID+0, '卓格巴尔从高台上跳了下来！', 41, 0, 100, 0, 0, 0, 104463, '纳拉萨斯'),
(91007, @GROUP_ID+0, @ID+0, '对。来抢我的圣锤试试啊！', 14, 0, 100, 0, 0, 54732, 103071, '达古尔'),
(91007, @GROUP_ID+1, @ID+0, '怎么可能？！我……是天选之……', 14, 0, 100, 0, 0, 54729, 103068, '达古尔 to Player'),
(91332, @GROUP_ID+0, @ID+0, '啮咬者会把你变成一堆碎石的！', 14, 0, 100, 0, 0, 0, 104640, '石爪猎手 to 岩背啮咬者'),
(101075, @GROUP_ID+0, @ID+0, '吞噬我血液中的力量吧！', 14, 0, 100, 0, 0, 0, 114792, '虫语虔信者'),
(102295, @GROUP_ID+0, @ID+0, '撕碎他们！', 14, 0, 100, 0, 0, 60773, 113522, '烬壳统御者'), -- BroadcastTextID: 53874 - 113522 - 104586
(105633, @GROUP_ID+0, @ID+0, '啊啊啊！！！', 14, 0, 100, 0, 0, 0, 103052, '顶石苦力 to 顶石苦力'), -- BroadcastTextID: 32694 - 54455 - 69043 - 69115 - 73962 - 74463 - 75340 - 76981 - 78041 - 83580 - 83582 - 83762 - 84199 - 90276 - 78041 - 79123 - 135125 - 118710 - 103052 - 100520 - 94167
(105636, @GROUP_ID+0, @ID+0, '入侵者？在这儿？！打垮他们！', 14, 0, 100, 0, 0, 0, 102910, '顶石苦力');

