INSERT IGNORE INTO `creature_text` (`CreatureID`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `BroadcastTextId`, `comment`) VALUES
(100497, @GROUP_ID+0, @ID+0, '你们应该逃跑的！现在，我要拿你们的骨头去喂风暴乌鸦！', 14, 0, 100, 0, 0, 58379, 106101, '乌索克 to Player'),
(100497, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\spell_druid_bearhug:20|t%s的|cFFFF0000|Hspell:198006|h[专注凝视]|h|r瞄准了|cFFFF0000$n|r！', 41, 0, 100, 0, 0, 58385, 106100, '乌索克 to Player'),
(100497, @GROUP_ID+2, @ID+0, '我要像拍扁树苗一样拍扁你们！', 12, 0, 100, 0, 0, 58385, 108500, '乌索克 to Player'),
(100497, @GROUP_ID+3, @ID+0, '|TInterface\\Icons\\ability_deathwing_assualtaspects:20|t%s陷入了|cFFFF0000|Hspell:198388|h[血性狂乱]|h|r！', 41, 0, 100, 0, 0, 58387, 106113, '乌索克'),
(100497, @GROUP_ID+4, @ID+0, '梦魇滋长，吞噬万物！', 14, 0, 100, 0, 0, 58387, 106107, '乌索克'),
(100497, @GROUP_ID+5, @ID+0, '梦魇的大幕已经升起……我终于从漫长的沉睡中……归来了。', 14, 0, 100, 0, 0, 58383, 106102, '乌索克 to Player'),
(102672, @GROUP_ID+0, @ID+0, '你们要找梦境？它也在找你们。', 14, 0, 100, 0, 0, 58662, 105003, '尼珊德拉'),
(102672, @GROUP_ID+1, @ID+0, '你的清醒是种病！', 14, 0, 100, 0, 0, 58671, 109017, '尼珊德拉 to Player'),
(102672, @GROUP_ID+2, @ID+0, '|TInterface\\Icons\\spell_nature_insect_swarm2:20|t尼珊德拉深呼吸，准备施放|cFFFF0404|Hspell:202977|h[感染吐息]|h|r！', 41, 0, 100, 0, 0, 58667, 106119, '尼珊德拉 to Breath Stalker'),
(102672, @GROUP_ID+3, @ID+0, '深呼吸，拥抱你的命运吧。', 14, 0, 100, 0, 0, 58667, 109011, '尼珊德拉 to Breath Stalker'),
(102672, @GROUP_ID+4, @ID+0, '让内心的黑暗吞噬你们！', 14, 0, 100, 0, 0, 58670, 109016, '尼珊德拉 to Player'),
(102672, @GROUP_ID+5, @ID+0, '我梦到了梦境。现在我醒了……', 14, 0, 100, 0, 0, 58665, 105002, '尼珊德拉 to 泽地歌唱者'),
(102679, @GROUP_ID+0, @ID+0, '生命的希冀已被斩断。梦游者一定会复仇的。', 14, 0, 100, 0, 0, 58510, 106175, '伊森德雷 to Player'),
(102679, @GROUP_ID+1, @ID+0, '来吧，梦游者们……复仇！', 14, 0, 100, 0, 0, 58500, 106176, '伊森德雷 to Player'),
(102679, @GROUP_ID+2, @ID+0, '漫长的梦境……终于降临了。', 14, 0, 100, 0, 0, 58499, 108558, '伊森德雷 to Player'),
(102681, @GROUP_ID+0, @ID+0, '和平稍纵即逝！让梦魇统治世界吧！', 14, 0, 100, 0, 0, 58509, 106181, '泰拉尔 to Player'),
(102682, @GROUP_ID+0, @ID+0, '我能感觉你内心的阴影。邪恶的侵蚀永无止境！', 14, 0, 100, 0, 0, 58508, 106179, '莱索恩'),
(103769, @GROUP_ID+0, @ID+0, '梦魇已经腐蚀了巨龙、神祇和传奇。你也将干脆利落地倒下！', 14, 0, 100, 0, 0, 58726, 109326, '萨维斯'),
(103769, @GROUP_ID+1, @ID+0, '我要让你远离现实世界！', 14, 0, 100, 0, 0, 58747, 109349, '萨维斯 to Player'),
(103769, @GROUP_ID+2, @ID+0, '我要一一踏平你们！', 14, 0, 100, 0, 0, 58750, 109352, '萨维斯'),
(103769, @GROUP_ID+3, @ID+0, '我的任务……还没……完成……', 14, 0, 100, 0, 0, 58746, 109346, '萨维斯 to Player'),
(104636, @GROUP_ID+0, @ID+0, '污染必须被净化！', 14, 0, 100, 0, 0, 58873, 109533, '塞纳留斯 to Player'),
(104636, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s开始施放|cFFFF0000|Hspell:212726|h[梦魇大军]|h|r！', 41, 0, 100, 0, 0, 58863, 111382, '塞纳留斯 to 塞纳留斯'),
(104636, @GROUP_ID+2, @ID+0, '攻击腐化者！', 14, 0, 100, 0, 0, 58863, 109522, '塞纳留斯 to 塞纳留斯'),
(104636, @GROUP_ID+3, @ID+0, '圣藤，缠住腐蚀者！', 14, 0, 100, 0, 0, 58869, 109528, '塞纳留斯'),
(104636, @GROUP_ID+4, @ID+0, '父亲！我……让你失望了……', 14, 0, 100, 0, 0, 58876, 109536, '塞纳留斯 to Player'),
(105393, @GROUP_ID+0, @ID+0, '来吧，小家伙们。品尝恐惧的滋味！', 15, 0, 100, 0, 0, 58911, 109119, '伊格诺斯 to Player'),
(105393, @GROUP_ID+1, @ID+0, '五把钥匙开启了我们的道路。五把火炬照亮了我们的前途。', 15, 0, 100, 0, 0, 58932, 109279, '伊格诺斯 to Player'),
(105393, @GROUP_ID+2, @ID+0, '终于，我们可以饱食一番了。', 15, 0, 100, 0, 0, 58912, 109121, '伊格诺斯 to Player'),
(105393, @GROUP_ID+3, @ID+0, '对我们的每一次攻击，都将被千倍奉还！', 15, 0, 100, 0, 0, 58921, 109141, '伊格诺斯 to Player'),
(105393, @GROUP_ID+4, @ID+0, '你们还要抵抗吗？还要拒绝这份恩赐吗？', 15, 0, 100, 0, 0, 58923, 109143, '伊格诺斯 to Player'),
(105393, @GROUP_ID+5, @ID+0, '恩佐斯……我将回归……尼奥罗萨……', 15, 0, 100, 0, 0, 58924, 109144, '伊格诺斯 to Player'),
(105906, @GROUP_ID+0, @ID+0, '伊格诺斯之眼正在制造梦魇恐魔！', 41, 0, 100, 0, 0, 0, 111379, '伊格诺斯之眼 to 梦魇恐魔'),
(106087, @GROUP_ID+0, @ID+0, '仁慈？休想！我只要奔涌的鲜血和破碎的尸体！', 14, 0, 100, 0, 0, 58625, 108989, '艾乐瑞瑟·雷弗拉尔'),
(106087, @GROUP_ID+1, @ID+0, '|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s宣布|cFFF00000|Hspell:212364|h[喂食时间]|h|r到了。', 41, 0, 100, 0, 0, 58618, 111635, '艾乐瑞瑟·雷弗拉尔'),
(106087, @GROUP_ID+2, @ID+0, '多么可口的小点心！', 14, 0, 100, 0, 0, 58618, 108981, '艾乐瑞瑟·雷弗拉尔'),
(106482, @GROUP_ID+0, @ID+0, '结束了！塞纳留斯被击败了，可我的导师还活着。现在我要集中力量净化他。', 12, 0, 100, 0, 0, 58899, 109563, '玛法里奥·怒风 to Player'),
(106482, @GROUP_ID+1, @ID+0, '萨维斯就在前面的裂隙里，那是梦魇的真正核心。如果有可能，我很想与你们并肩作战，可我……不能进去。', 12, 0, 100, 0, 0, 58900, 109564, '玛法里奥·怒风 to Player'),
(106482, @GROUP_ID+2, @ID+0, '我与梦境的联系赋予了我强大的力量……可这也让我无法抵抗裂隙中的黑暗。我曾窥视过它，知道这是真的。只要踏进那里，我就会迷失……像塞纳留斯一样。', 12, 0, 100, 0, 0, 69640, 109565, '玛法里奥·怒风 to Player'),
(106482, @GROUP_ID+3, @ID+0, '去吧，消灭梦魇之王。只有这样，梦境才能恢复……艾泽拉斯才能得救。', 12, 0, 100, 0, 0, 69639, 109566, '玛法里奥·怒风 to Player'),
(106482, @GROUP_ID+4, @ID+0, '梦魇之虹上有塞纳留斯的气息。它是通往月光林地的传送门，但被黑暗魔法封锁了。我们得斩断束缚它的能量触须。', 14, 0, 100, 0, 0, 61373, 112987, '玛法里奥·怒风 to Player'),
(106482, @GROUP_ID+5, @ID+0, '这里每条道路都散发着邪气。选一条路吧，我会一直陪着你们的。', 14, 0, 100, 0, 0, 61374, 112988, '玛法里奥·怒风 to Player'),
(115784, @GROUP_ID+0, @ID+0, '啾！', 12, 0, 100, 0, 0, 0, 124300, '雪羽雏龙 to 雪羽雏龙');

