INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES 
(98542, 0, 0, 'zhCN', '消灭！吞噬！'),
(98542, 1, 0, 'zhCN', '收割时间到！'),
(98542, 2, 0, 'zhCN', '离开这个微不足道的躯壳，加入我们的行列……'),
(98542, 3, 0, 'zhCN', '我要享用你的精华……'),
(98542, 4, 0, 'zhCN', '黑鸦堡垒的古代幽灵，来加入合唱吧！'),
(98542, 5, 0, 'zhCN', '我要享用你的精华……'),
(98542, 6, 0, 'zhCN', '这……这力量……太强大了！'),
(98696, 0, 0, 'zhCN', '你们将葬身此地，蠢货。'),
(98696, 1, 0, 'zhCN', '你无路可逃了。'),
(98696, 2, 0, 'zhCN', '狩猎不会结束……'),
(98696, 3, 0, 'zhCN', '不！我现在明白了……背……叛……'),
(98706, 0, 0, 'zhCN', '兄弟姐妹们，入侵者冲我们来了。击退他们！进攻！'),
(98792, 0, 0, 'zhCN', '哈！我们会用这些大石头解决他们的！'),
(98792, 1, 0, 'zhCN', '啊！他们来了！快跑！'),
(98792, 2, 0, 'zhCN', '呃……噢……哇啊啊啊！！！！'),
(98792, 3, 0, 'zhCN', '啊！我们很抱歉！我们保证！'),
(98810, 0, 0, 'zhCN', '%s变得狂怒无比！'),
(98949, 0, 0, 'zhCN', '用你们的鲜血染红城堡！'),
(98949, 1, 0, 'zhCN', '别费劲逃跑了，跳蚤……'),
(98949, 2, 0, 'zhCN', '哈！抓住你了！'),
(98949, 3, 0, 'zhCN', '在我脚下颤栗吧。'),
(98949, 4, 0, 'zhCN', '但是……我不可能……输……'),
(98965, 0, 0, 'zhCN', '恶魔，你们休想占据这个世界！'),
(98970, 0, 0, 'zhCN', '现在，睡吧……'),
(99857, 0, 0, 'zhCN', '我……现在明白了。你……你必须找到库塔洛斯。你必须阻止这一切。');

