DELETE FROM `creature_text` WHERE (`CreatureID`=32638 ) OR (`CreatureID`=32639 ) OR (`CreatureID`=61156 ) OR (`CreatureID`=61203 )  OR (`CreatureID`=61342 )  OR (`CreatureID`=61350 ) OR (`CreatureID`=61461 ) OR (`CreatureID`=61462 ) OR (`CreatureID`=62706 ) OR (`CreatureID`=65271 ) ;
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `comment`) VALUES
(32638, @GROUP_ID+0, @ID+0, '你为什么要这样对待哈克穆德？', 12, 0, 100, 6, 0, 0, 33015, '阿古斯的哈克穆德 to Player'),
(32639, @GROUP_ID+0, @ID+0, '再见！你曾经是尼莫最好的朋友！', 12, 0, 100, 3, 0, 0, 33020, '尼莫 to Player'),
(61156, @GROUP_ID+0, @ID+0, '跑吧，懦夫！乡巴佬！这片土地将重归自然的怀抱！', 14, 0, 100, 0, 0, 0, 60741, '仇灰'),
(61203, @GROUP_ID+0, @ID+0, '非常感谢……我已经坚持不了多久了。', 12, 0, 100, 2, 0, 0, 60930, '酒仙曲子 to Player'),
(61203, @GROUP_ID+1, @ID+0, '唉，我无法继续前行了。要是我们的绿石佳酿没被偷光就好了！', 12, 0, 100, 396, 0, 0, 62401, '酒仙曲子 to Player'),
(61203, @GROUP_ID+2, @ID+0, '如果你有胆量进入周围的森林，把被盗的酒桶找回来带给我，我就会为你调制一种具有神奇力量的浓缩生啤……', 12, 0, 100, 397, 0, 0, 66255, '酒仙曲子 to Player'),
(61203, @GROUP_ID+3, @ID+0, '这可以给那些窃取我们道场珍贵产品的小偷们一个教训！', 14, 0, 100, 71, 0, 0, 66251, '酒仙曲子 to Player'),
(61203, @GROUP_ID+4, @ID+0, '啊，物归原主了。谢谢你！', 14, 0, 100, 71, 0, 0, 66252, '酒仙曲子 to Player'),
(61203, @GROUP_ID+5, @ID+0, '我们的佳酿回来了！我们所有人都由衷地感谢你。', 14, 0, 100, 71, 0, 0, 66254, '酒仙曲子 to Player'),
(61203, @GROUP_ID+6, @ID+0, '一位冒险家挽救了村庄，而一位英雄将美酒物归原主！', 14, 0, 100, 1, 0, 0, 66253, '酒仙曲子 to Player'),
(61203, @GROUP_ID+7, @ID+0, '啊，你回来了！太感谢你了。拜托，请你一定要收下这个。这是我们这儿最烈的酒：烈性绿石佳酿。', 12, 0, 100, 1, 0, 0, 60931, '酒仙曲子 to Kobold Miner'),
(61342, @GROUP_ID+0, @ID+0, '救命！救命！', 14, 0, 100, 20, 0, 23279, 60978, '木艺师刘波 to Player'), -- BroadcastTextID: 41830 - 60978 - 83727 - 83727 - 86591
(61342, @GROUP_ID+1, @ID+0, '非常感谢！', 12, 0, 100, 1, 0, 961, 60398, '木艺师刘波 to Kobold Miner'), -- BroadcastTextID: 60398 - 60684
(61350, @GROUP_ID+0, @ID+0, '我还以为我死定了呢。太感谢你了！', 12, 0, 100, 1, 0, 963, 60966, '优雅的斯万 to Kobold Miner'),
(61461, @GROUP_ID+0, @ID+0, '绿石村有救了！谢谢你！', 12, 0, 100, 1, 0, 961, 60965, '大块头尚林 to Kobold Miner'),
(61462, @GROUP_ID+0, @ID+0, '太感谢你了！', 12, 0, 100, 1, 0, 0, 60964, '美娜 to Kobold Miner'), -- BroadcastTextID: 7 - 22652 - 53554 - 60964 - 87257
(62706, @GROUP_ID+0, @ID+0, '咦！怪物们在攻击绿石村！快跑！', 14, 0, 100, 0, 0, 23279, 62217, '怯懦的祖音 to Player'),
(65271, @GROUP_ID+0, @ID+0, '它们占领了村子！救命啊！', 14, 0, 100, 20, 0, 29809, 60980, '林村长 to Player'),
(65271, @GROUP_ID+1, @ID+0, '由于我们雇用冒险者帮忙驱赶那些淘气的精灵，土灵仇灰为此大发雷霆。', 12, 0, 100, 1, 0, 961, 67528, '林村长 to Kobold Miner'),
(65271, @GROUP_ID+2, @ID+0, '我能理解他的烦乱，可这攻击也太过分了！', 12, 0, 100, 5, 0, 963, 67529, '林村长 to Kobold Miner');

