(48723, 'zhCN', '警卫泰诺斯', '', '', '', '', '', '', '', '', 26365),
(48696, 'zhCN', '牧羊人卡沃斯', '', '', '', '', '', '', '', '', 26365),
(48689, 'zhCN', 'Lockout Tracking - Boss - Marsh', '', '', '', '', '', '', '', '', 26365),
