(120036, @GROUP_ID+1, @ID+0, '让我去对付他们！', 12, 0, 100, 0, 0, 80815, 126362, '希萨莉·黑鸦 to Player'),
(120036, @GROUP_ID+2, @ID+0, '尝尝我的爪子吧！', 12, 0, 100, 0, 0, 80818, 0, '希萨莉·黑鸦'),
