INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `comment`) VALUES
(32642, @GROUP_ID+0, @ID+0, 'Be dat way den!', 12, 0, 100, 1, 0, 0, 33029, 'Mojodishu to Player'),
(62821, @GROUP_ID+1, @ID+0, '我无意针对你创立法规。', 12, 0, 100, 3, 0, 6515, 63975, '秘法师鸟羽帽 to Player'),
(97989, @GROUP_ID+0, @ID+0, '加尼尔遭到了威胁？那么我们不能再浪费时间了。', 12, 0, 100, 0, 0, 0, 0, '传说中的叶须 to Player'),
(98027, @GROUP_ID+2, @ID+0, '日安，$ct。', 12, 0, 100, 0, 0, 62245, 0, 'Laughing Sister to Player'),
(98027, @GROUP_ID+1, @ID+0, '森林中的一切都是那么美妙，$ct。', 12, 0, 100, 0, 0, 0, 0, 'Laughing Sister to Player'),
(98027, @GROUP_ID+0, @ID+0, 'Hi, $ct!！', 12, 0, 100, 0, 0, 0, 0, 'Laughing Sister to Player'),
(101195, @GROUP_ID+0, @ID+0, '梦魇的扩散比我们预想的还远。我要好好想想，大德鲁伊。', 12, 0, 100, 396, 0, 70996, 121599, '伦萨·巨蹄 to Player'),
(104349, @GROUP_ID+0, @ID+0, '梦境的情况恐怕比我们想的还要糟。', 12, 0, 100, 0, 0, 62240, 106846, '纳拉雷克斯 to Player'),
(104349, @GROUP_ID+1, @ID+0, '现在，放松，把精神集中到梦境里。我会指引你的灵魂。', 12, 0, 100, 0, 0, 62235, 106848, '纳拉雷克斯 to Player'),
(104398, @GROUP_ID+0, @ID+0, '我还以为死定了呢！', 12, 0, 100, 0, 0, 62226, 106906, '巴珊娜·符文图腾 to 巴珊娜·符文图腾'),
(104398, @GROUP_ID+1, @ID+0, '最好别跟这些恐魔交战。我们溜过去！', 12, 0, 100, 0, 0, 62227, 106907, '巴珊娜·符文图腾 to 巴珊娜·符文图腾'),
(104573, @GROUP_ID+0, @ID+0, '要不是你及时赶到，我肯定会被击垮。谢谢。', 12, 0, 100, 2, 0, 62233, 107004, '莱莎·护蕾 to Player'),
(104573, @GROUP_ID+1, @ID+0, '现实世界见。', 12, 0, 100, 0, 0, 62234, 107005, '莱莎·护蕾 to Player'),
(104577, @GROUP_ID+0, @ID+0, '愿古树赐福予我们。', 12, 0, 100, 0, 0, 62211, 107061, '莱莎·护蕾 to Player'),
(104577, @GROUP_ID+1, @ID+0, '我守护了加尼尔几百年。可今天，它差点被腐蚀了。是时候让别人来接替我了。', 12, 0, 100, 0, 0, 62216, 107326, '莱莎·护蕾 to Player'),
(104577, @GROUP_ID+2, @ID+0, '因此，我决定将我的位置传给$p，一位真正的生命保护者……和梦境守护者！', 12, 0, 100, 0, 0, 62217, 107327, '莱莎·护蕾 to Player'),
(104577, @GROUP_ID+3, @ID+0, '再次感谢，大导师。我会留在梦境林地。如果你需要指导，就来找我吧。', 12, 0, 100, 0, 0, 62218, 107328, '莱莎·护蕾 to Player'),
(104658, @GROUP_ID+0, @ID+0, '%s身受重伤，单膝跪了下来。', 16, 0, 100, 0, 0, 0, 0, '岑塔布拉 to 迪托马斯'),
(104658, @GROUP_ID+1, @ID+0, '%s|cFFFF0404|Hspell:204237|h[严重受伤]|h|r，在经过治疗前无法继续战斗了！', 41, 0, 100, 0, 0, 0, 0, '岑塔布拉 to 迪托马斯'),
(110398, @GROUP_ID+0, @ID+0, '没错，我有莎拉达希尔根须的鞭笞者种子。', 12, 0, 100, 0, 0, 66745, 111956, '纳拉雷克斯 to Player'),
(110398, @GROUP_ID+1, @ID+0, '拿上种子，种到这边的泥土里。', 12, 0, 100, 1, 0, 66741, 111957, '纳拉雷克斯 to Player'),
(113525, @GROUP_ID+0, @ID+0, '米露恩一边抽泣，一边努力深呼吸。', 16, 0, 100, 0, 0, 0, 0, '米露恩 to Player'),
(113525, @GROUP_ID+1, @ID+0, '我们能行，$n。加尼尔就靠我们了！', 12, 0, 100, 0, 0, 62245, 106807, '米露恩 to Player');


