INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `locale`, `Text`) VALUES
(32642, @GROUP_ID+0, @ID+0, 'zhCN', '那就这样吧！'),
(62821, @GROUP_ID+1, @ID+0, 'zhCN', '我无意针对你创立法规。'),
(97989, @GROUP_ID+0, @ID+0, 'zhCN', '加尼尔遭到了威胁？那么我们不能再浪费时间了。'),
(98027, @GROUP_ID+2, @ID+0, 'zhCN', '日安，$ct。'),
(98027, @GROUP_ID+1, @ID+0, 'zhCN', '森林中的一切都是那么美妙，$ct。'),
(98027, @GROUP_ID+0, @ID+0, 'zhCN', '嗨，$ct！'),
(101195, @GROUP_ID+0, @ID+0, 'zhCN', '梦魇的扩散比我们预想的还远。我要好好想想，大德鲁伊。'),
(104349, @GROUP_ID+0, @ID+0, 'zhCN', '梦境的情况恐怕比我们想的还要糟。'),
(104349, @GROUP_ID+1, @ID+0, 'zhCN', '现在，放松，把精神集中到梦境里。我会指引你的灵魂。'),
(104398, @GROUP_ID+0, @ID+0, 'zhCN', '我还以为死定了呢！'),
(104398, @GROUP_ID+1, @ID+0, 'zhCN', '最好别跟这些恐魔交战。我们溜过去！'),
(104573, @GROUP_ID+0, @ID+0, 'zhCN', '要不是你及时赶到，我肯定会被击垮。谢谢。'),
(104573, @GROUP_ID+1, @ID+0, 'zhCN', '现实世界见。'),
(104577, @GROUP_ID+0, @ID+0, 'zhCN', '愿古树赐福予我们。'),
(104577, @GROUP_ID+1, @ID+0, 'zhCN', '我守护了加尼尔几百年。可今天，它差点被腐蚀了。是时候让别人来接替我了。'),
(104577, @GROUP_ID+2, @ID+0, 'zhCN', '因此，我决定将我的位置传给$p，一位真正的生命保护者……和梦境守护者！'),
(104577, @GROUP_ID+3, @ID+0, 'zhCN', '再次感谢，大导师。我会留在梦境林地。如果你需要指导，就来找我吧。'),
(104658, @GROUP_ID+0, @ID+0, 'zhCN', '%s身受重伤，单膝跪了下来。'),
(104658, @GROUP_ID+1, @ID+0, 'zhCN', '%s|cFFFF0404|Hspell:204237|h[严重受伤]|h|r，在经过治疗前无法继续战斗了！'),
(110398, @GROUP_ID+0, @ID+0, 'zhCN', '没错，我有莎拉达希尔根须的鞭笞者种子。'),
(110398, @GROUP_ID+1, @ID+0, 'zhCN', '拿上种子，种到这边的泥土里。'),
(113525, @GROUP_ID+0, @ID+0, 'zhCN', '米露恩一边抽泣，一边努力深呼吸。'),
(113525, @GROUP_ID+1, @ID+0, 'zhCN', '我们能行，$n。加尼尔就靠我们了！');

